(window.GIM_TS=window.GIM_TS||{})["Meilah.1"]={"from":24,"a":[["במשנה הוזכר ענין עבודה זרה (אשירה). ובקשר לזה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדין \u0003עבודה זרה שנשתברה מאליה. ר' יוחנן אמר:\u0004 הריהי \u0003אסורה\u0004 בהנאה, שלא נתבטלה בשבירה זו. \u0003וריש לקיש אמר:\u0004 \u0003מותרת\u0004 בהנאה.","ומסבירים את שיטותיהם: \u0003ר' יוחנן אמר\u0004 שהיא \u0003אסורה\u0004 — שהרי \u0003לא בטלה\u0004 ה\u0003גוי,\u0004 שרק כאשר הגוי משברה בידים הריהי בטילה. \u0003וריש לקיש אמר\u0004 שהיא \u0003מותרת\u0004 — שכן הגוי, כיון שרואה שהעבודה זרה נשברה, \u0003מימר אמר\u0004 \u0005[אומר]\u0006 הוא לעצמו: \u0003היא\u0004 העבודה זרה את \u0003גופה\u0004\u0005[עצמה]\u0006 \u0003לא מצלה\u0004\u0005 [מצילה] \u0006 את עצמה מלהישבר, האם \u0003לדידי מצלה לי\u0004 \u0005[אותי עצמי היא תציל]?\u0006 ולפיכך מבטלה בלבו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 ממה ששנינו במשנתנו: \u0003הקן ש\u0004נמצא \u0003בראש האילן של הקדש\u0004 — אין נהנין ממנו, \u0003ו\u0004אם נהנו — \u0003אין מועלין\u0004 בו. ואילו \u0003שב\u0004ראש אילן של \u0003אשירה\u0004 — לא יטפס על העץ כדי לקחת את הקן אלא \u0003יתיז\u0004 אותו \u0003בקנה.\u0004","ונדון בהלכה השניה: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן באופן שבנתה הציפור את הקן ממה \u0003דאיתבר\u0004 \u0005[שנשבר]\u0006 על ידי הציפור \u0003מגופה\u0004 של האשירה שבה היא מקננת, \u0003וקתני\u0004 \u0005[ושנה]\u0006 התנא במשנתנו שאמנם אסור לטפס על העץ כדי לקחת את הקן, אבל \u0003יתיז בקנה.\u0004 והרי שמותר להשתמש בעבודה זרה שנשברה מאליה, ולא בידי הגוי. השיב ר' יוחנן לריש לקיש: \u0003לא,\u0004 אין להביא ראיה ממשנתנו, כיון שמדובר בה באופן \u0003דאייתי\u0004 \u0005[שהביאה]\u0006 הציפור את עצי הקן מ\u0003עצים מעלמא\u0004 \u0005[סתם,\u0006 שאינם של עבודה זרה\u0005]\u0006 ולא מן האשירה עצמה.","מקשה על כך ריש לקיש: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 שנינו בתחילת המשנה שקן הנמצא בראש אילן \u0003של הקדש אין נהנין\u0004 ממנו \u0003ואין מועלין\u0004 בו, והרי אף בהלכה זו ודאי אין עצי הקן משל הקדש, ומותרים הם אם כן בהנאה אף מלכתחילה?","\u0003אלא\u0004 צריך לומר שהמשנה מדברת בעצי הקן הבאים מהעץ בו מקננת הציפור, ומדובר \u0003בגידולין הבאין\u0004 (הצומחים) באילן \u0003לאחר מכאן\u0004 (לאחר שהוקדש העץ), \u0003וקסבר\u0004 \u0005[וסבור הוא]\u0006 התנא שבמשנתנו כי \u0003אין מועלין בגידולין\u0004 של הקדש אם נהנו מהם, ואולם אסור להנות מהם לכתחילה.","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להעמיד את משנתנו כשהביאה הציפור את עצי הקן מאותו אילן בו היא מקננת, משום \u0003דאי סלקא דעתך דאייתי מעלמא\u0004 \u0005[שאם עולה על דעתך\u0006 שמדובר באופן \u0005ש\u0006הציפור \u0005הביאה\u0006 את העצים \u0005מסתם\u0006 אילנות\u0005], אמאי\u0006 \u0005[מדוע]\u0006 באילן של אשירה \u0003יתיז\u0004 את הקן \u0003בקנה? לשקליה משקל\u0004 \u0005[שיקח אותו]\u0006 במישרין, אף בלא קנה!","\u0003אמר ר' אבהו, אמר ר' יוחנן\u0004 בדחיית הקושיה: \u0003לעולם\u0004 מדובר במשנתנו \u0003דאייתי מעלמא\u0004 \u0005[שהביאה\u0006 הציפור את עצי הקן \u0005מסתם\u0006 אילנות\u0005],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 הכוונה במה ששנינו \u0003\"יתיז\u0004 במקל\"? אין הכוונה לקן עצמו, אלא ל\u0003אפרוחים\u0004 המצויים בו. שאין לעלות על עץ האשירה ולקחתם, שהרי נהנה הוא מעץ עבודה זרה (המשמש אותו בעלייתו). ועצי הקן עצמו אסורים בהנאה מדברי חכמים, מפני החשש שמא יבואו אף לקחת עצי קן שנלקחו מאילן האשירה עצמו (והרי אלו אסורים מן התורה, כיון שלא שברם הגוי) (תוס').","בדינם של האפרוחים והביצים הנמצאים בקן שבאילן של הקדש או אשירה, \u0003אמר ליה\u0004 \u0005[לו] ר' יעקב לר' ירמיה:\u0006 ה\u0003אפרוחים\u0004 הנמצאים \u0003כאן וכאן,\u0004 בין באילן של הקדש בין באילן של אשירה — הריהם \u0003מותרין\u0004 בהנאה, כיון שהם יכולים לפרוח ולקנן בכל מקום, ואין הם נזקקים דווקא לאילן זה האסור בהנאה. ואילו ה\u0003ביצים\u0004 הנמצאות \u0003כאן וכאן,\u0004 כיון שהן נזקקות לאילן זה — \u0003אסורין\u0004 בהנאה. \u0003אמר רב אשי:\u0004 אף האפרוחים, \u0003אם\u0004 היו \u0003אפרוחים\u0004 צעירים שעדיין \u0003צריכין לאמן\u0004 — \u0003כביצים דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 ואסורים בהנאה.","\u0003הגזברים\u0004 שבמקדש \u0003שלקחו\u0004 (קנו) \u0003עצים\u0004 של חולין לצורך תיקון בנין המקדש — \u0003מועלין בעצים\u0004 עצמם, \u0003ו\u0004אולם \u0003אין מועלין לא בשיפויי\u0004 (הנסורת שיוצאת מהם) \u0003ולא בנבייה\u0004 (העלים הנופלים מהם), משום שהגזברים לא קנו להקדש אלא את הדבר שניתן להשתמש בו לבנין המקדש, ואין אלה בכלל זה.","\u0003אמר שמואל,\u0004 כך נוהגים במקדש בשעה שבאים לבנות בו, לצורך תיקונו ושיפוצו: בתחילה \u0003בונין ב\u0004חומרי הבנייה (העצים והאבנים) של \u0003חול, ו\u0004רק \u0003אחר כך\u0004 בגמר המלאכה היו \u0003מקדישין\u0004 אותם.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין מקדישים אותם מייד? — כי \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003מתנדב מעות\u0004 לבדק הבית, הריהו \u0003מקדש להו\u0004 \u0005[אותן]\u0006 מעות, ושוב אינו יכול להשתמש בהם לדבר חולין, שהרי בכך מועל בהם. ואין איפוא דרך לקנות בהם דבר לבדק הבית, שהרי מיד כשיקבל המוכר את המעות ימעל בהן, ונמצא שאי אפשר לבנות במקדש ממעות שנתנו להקדש אלא באופן \u0003דאמר\u0004 \u0005[ש\u0006המקדיש \u0005אומר]\u0006 בשעה שמקדיש את המעות: \u0003\"תיחול\u0004 \u0005[תחול]\u0006 \u0003קדושת מעות\u0004 אלה על ה\u0003בנין\u0004 עצמו משיגמר בניינו\", ולא על חומרי הבנין או על שכר האומנים בשעה שהם עובדים. ולכן אין הגזבר יכול לתת ממעות אלה לפועלים.","ואולם משנגמרה מלאכת הבנין, מתחללות המעות הללו על הבנין, והריהן חולין, \u0003ו\u0004מעתה \u0003יהיב להון\u0004 \u0005[נותן\u0006 הגזבר \u0005אותן]\u0006 \u0003לאומנין\u0004 שעבדו בבנין זה של המקדש \u0003בשכרן\u0004 ולאלה שסיפקו את חומרי הבנין."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במשנה במסכת שקלים: \u0003מותר הקטרת\u0004 שנשארה מהשנה שעברה, ואין היא ראויה להקטרה, \u0003מה היו עושין בו\u0004 במותר זה, על מנת שיוכשר לשנה הבאה? — \u0003היו מפרישין ממנה\u0004 ממותר הקטורת כערך \u0003שכר האומנין\u0004 העובדים במקדש, ומזכים אותה להם (באמצעות אחד הגזברים שזוכה אותה עבורם). \u0003ו\u0004לאחר שזכו בה האומנים, \u0003מחללין אותה,\u0004 את הקדושה שבמותר הקטורת, \u0003על מעות\u0004 חולין כערך שכר \u0003האומנין. ו\u0004אז, לאחר שהתחללה הקטורת במעות הללו, והריהי איפוא מעתה חולין, \u0003נותנין אותה לאומנין\u0004 בשכרם, \u0003וחוזרין ונוטלין\u0004 (קונים) \u0003אותה\u0004 מהאומנים \u0003מ\u0004כספי \u0003תרומה חדשה\u0004 של השנה החדשה, ונמצא שקטורת זו באה מהתרומה החדשה.","","ומקשים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נהגו כן? שהרי לשיטת שמואל שבונים בחול ואחר כך מקדישים, אף כאן יפרישו ממותר זה כשכר הראוי להם, ו\u0003ליחליה\u0004 \u0005[שיחלל]\u0006 את מותר הקטורת על ה\u0003בנין\u0004 בעודו של חול, ותחול קדושת הקטורת עליו, ויחזרו ויחללו קדושה זו של הקטורת על כספי התרומה החדשה ויקנו בה בחזרה אותו מותר הקטורת? ומשיבים: מדובר במשנה זו באופן ש\u0003לא איכא\u0004 \u0005[לא נמצא]\u0006 עתה עבודה של \u0003בנין\u0004 בבית המקדש, ואין איפה במה לחלל את מותר הקטורת. ומקשים על תירוץ זה: \u0003והא\u0004 \u0005[והרי]\u0006 במשנה זו \u0003\"מעות האומנין\" קתני\u0004 \u0005[שנינו],\u0006 הרי שאנו עוסקים בפועלים הבונים במקדש. ומתרצים: אכן מדובר במשנה זו בזמן שבונים במקדש, ואולם מדובר באופן \u0003דליכא\u0004 \u0005[שאין]\u0006 שוויה של מלאכת ה\u0003בנין כשיעור מעות\u0004 מותר הקטורת, ולכן אין אפשרות לחלל את מותר הקטורת על בנין זה.","","ומקשים על תירוץ זה: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 בדין חילול ההקדש, שאף \u0003הקדש\u0004 ה\u0003שוה מנה ש\u0004עמד הגזבר ו\u0003חיללו על\u0004 הדבר ה\u0003שוה פרוטה\u0004 בלבד — הרי הקדש זה \u0003מחולל\u0004 בכך, ואין צורך שיהיה דווקא בשוויו! ומשיבים: הני מילי \u0005[דברים אלה]\u0006 שאמר שמואל נאמרו באופן \u0003דאי עבד\u0004 \u0005[שאם\u0006 עבר הגזבר ו\u0005עשה]\u0006 — הריהו חל בדיעבד, ואולם \u0003לכתחלה\u0004 — לא נכון לעשות כן. \u0003רב\u0004","\u0003פפא אמר\u0004 תירוץ אחר: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 לשיטתו של שמואל ש\u0003בונין בחול\u0004 ואחר כך מקדישים, לפי ש\u0003לא נתנה תורה למלאכי השרת\u0004 שאין בהם עייפות וצורכי הגוף, אלא לבני אדם, ומשום כך \u0003אמרי\u0004 \u0005[אמרו]\u0006 חכמים שיש לחשוש \u0003דלמא בעי למיזגא\u0004 \u0005[שמא רוצה\u0006 הפועל לנוח מעט, ו\u0005לשבת]\u0006 על אבני הבנין הנבנים על ידו, \u0003ו\u0004אכן \u0003זגא עלייהו\u0004 \u0005[ישב עליהם].\u0006 ו\u0003אי בנא בקודשא\u0004 \u0005[ואם\u0006 הוא \u0005בונה בקודש]\u0006 — \u0003אישתכח דקמעיל בקודשא\u0004 \u0005[נמצא ש\u0006בכך \u0005הוא מועל בקדשים].\u0006 ולכן, מוטב שיבנו הפועלים בחול, ורק אחר כך יקדישו את הבנין.","ושואלים על סברה זו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]: הגזברין שלקחו את העצים\u0006 של חולין לצורך בנין המקדש — \u0003מועלין בהן, ואין מועלין לא בשיפויי ולא בנבייה. ו\u0004מעתה יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מועלין בהן\u0004 בעצים? \u0003הכא נמי ליעבד\u0004 \u0005[כאן גם כן שיעשה]\u0006 \u0003בחול,\u0004 כלומר, שלא יקדישם הגזבר מיד, אלא לאחר שייקבעו בבנין, שאף כאן נאמר כי \u0003אמרי\u0004 \u0005[אמרו]\u0006 חכמים \u0003דדלמא בעי למיזגא, וזגא\u0004 \u0005[כי שמא ירצה לשבת, וישב]\u0006 \u0003עליהן, ואישתכח דקא\u0004 \u0005[ונמצא שהוא]\u0006 \u0003מועל בקדשים!\u0004 \u0003אמר רב פפא: אי\u0004 \u0005[אם]\u0006 המדובר \u0003בעצים\u0004 שקנו הגזברים לצורך בנין המקדש \u0003דמכאן ואילך\u0004 \u0005[שמכאן והלאה],\u0006 שמייעדים את העצים לבנייה בעתיד — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לא יקדישו אותם אלא לאחר שייקבעו בבנין. \u0003אלא כי תנן במתניתין\u0004 \u0005[כאשר שנינו במשנתנו]\u0006 שמועלים בעצים, מדובר \u0003בעצים\u0004 שנקנו לבנייה \u0003דיומיה\u0004","","",""],["כל \u0003קדשי\u0004 ה\u0003מזבח\u0004 (הראויים להקרבה על המזבח) למיניהם, \u0003מצטרפין זה עם זה ל\u0004כדי שיעור אחד החשוב כ\u0003מעילה,\u0004 שהיא ההנאה בשוה פרוטה. שאם עבר אדם ונהנה מכמה קדשי מזבח, אף שבכל אחד מהם נהנה בפחות משוה פרוטה, כיון שהצטרפו כולם לכדי הנאה בשוה פרוטה — התחייב בכך בדין המעילה. \u0003ו\u0004כן מצטרפים כל קדשי המזבח \u0003ל\u0004שיעור כזית (שהוא שיעור האכילה המחייב), כדי שיהיה בו ל\u0003חייב עליהם משום\u0004 אכילת \u0003פיגול\u0004 (הקרבן שחשב הכהן בשעת עבודתו לאוכלו לאחר זמנו הראוי) \u0003ונותר\u0004 (שנותר מן הקרבן לאחר זמן אכילתו הראוי) \u0003וטמא\u0004 (האוכל קדשים בטומאת הגוף), אף שבכל אחד מהם כשלעצמו אין שיעור כזית. וכן הדין בנהנה מ\u0003קדשי בדק הבית\u0004 השונים, ש\u0003מצטרפין\u0004 הם \u0003זה עם זה\u0004 לכדי שיעור מעילה. וכמו כן מצטרפים שניהם, קדשי מזבח וקדשי בדק הבית, לכדי שיעור אחד למעילה, שאם נהנה מן הקדשים \u0003אחד קדשי מזבח ואחד קדשי בדק הבית,\u0004 ואין בכל אחד מאלה כשלעצמו שיעור כזית, הריהם \u0003מצטרפין זה עם זה, ל\u0004חייבו ב\u0003מעילה.\u0004","ושואלים: \u0003השתא\u0004 \u0005[עתה]\u0006 \u0003יש לומר\u0004 מתוך \u0003דקתני\u0004 \u0005[\u0006\u0005ששונה]\u0006 התנא בסופה של המשנה \u0003אחד קדשי מזבח ואחד קדשי בדק הבית\u0004 מצטרפים זה לזה, אף \u0003דהאי\u0004 \u0005[שזה]\u0006 האחד (קדשי מזבח) קדושתו היא \u0003קדושת הגוף, ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 האחד (קדשי בדק הבית) קדושתו היא \u0003קדושת דמים,\u0004 ו\u0003אפילו הכי\u0004 \u0005[כך],\u0006 \u0003קתני\u0004 \u0005[הוא\u0006 התנא \u0005שונה]\u0006 שהם \u0003מצטרפין זה עם זה.\u0004 מעתה, הלכה זו שמצטרפים \u0003קדשי מזבח עם קדשי מזבח\u0004 שנאמרה בתחילתה \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?\u0006","ומשיבים: נצרך התנא להשמיענו הלכה זו \u0003משום דקתני עלה\u0004 \u0005[שהוא שונה עליה]\u0006 הלכה נוספת שמצטרפים קדשי המזבח זה עם זה \u0003לחייב עליהן משום פיגול נותר וטמא,\u0004 ואילו בקדשי מזבח המצטרפים ל\u0003קדשי בדק הבית לא איכא הכי\u0004 \u0005[לא נמצא כך]\u0006 שתנהג הלכה זו (שהרי אין דין פיגול נותר וטמא שייך בקדשי בדק הבית), \u0003משום הכי\u0004 \u0005[כך],\u0006 \u0003קא פליג ליה\u0004 \u0005[הוא,\u0006 התנא, \u0005מחלק אותו]\u0006 הדין בשני חלקי המשנה שלפנינו.","שנינו במשנה שיש דין מעילה בקדשי בדק הבית. ובאותו ענין \u0003אמר ר' ינאי: מחוורתא\u0004 \u0005[ברור]\u0006 הוא הדין מן התורה כי \u0003אין חייבין משום מעילה אלא על קדשי בדק הבית ו\u0004קרבן \u0003עולה בלבד. מאי טעמא\u0004 \u0005[מה טעם,\u0006 מקור הדבר\u0005]?\u0006 — שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"נפש כי תמעל מעל\u0004 וחטאה בשגגה \u0003מקדשי ה' \"\u0004(ויקרא ה, טו), ובא הכתוב ללמדנו: דווקא ה","\u0003קדשים המיוחדין לה',\u0004 שהם קדשי בדק הבית, שהכל להקדש — \u0003יש בהן\u0004 דין \u0003מעילה. אבל קדשי מזבח\u0004 שאין כולם להקדש, שהרי \u0003אית בהו\u0004 \u0005[יש בהם]\u0006 קרבנות (כחטאת וכאשם) שחלק מהם ניתן \u0003לכהנים, ואית בהו\u0004 \u0005[ו\u0006כן \u0005יש בהם]\u0006 חלק הניתן \u0003לבעלים,\u0004 אין הם בכלל המיוחדים לה' (\"מקדשי ה' \") שיש בהם דין מעילה.","ומקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003קדשי מזבח מצטרפין זה עם זה למעילה,\u0004 והרי שיש דין מעילה בקדשי מזבח! ומתרצים: כוונת משנתנו למעילה \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006","ומקשים עוד ממה ששנינו במשנה בתחילת המסכת: \u0003קדשי קדשים\u0004 כגון החטאת והאשם, \u0003ששחטן בדרום\u0004 העזרה, שלא במקומם הראוי, ונפסלו בכך — \u0003מועלים בהן.\u0004 הרי שיש בקדשי מזבח דין מעילה! ומשיבים: אף הלכה זו \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006","ושואלים עוד, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003הנהנה מן ה\u0004בהמה שהוקדשה לקרבן \u0003חטאת כשהיא\u0004 עדיין \u0003חיה,\u0004 וכגון שרכב עליה — \u0003לא מעל\u0004 בהנאתו זו, \u0003עד שיפגום\u0004 (יחסיר מערכה של חטאת זו) בשווי פרוטה. הנהנה מן החטאת \u0003כשהיא מתה, כיון שנהנה כל שהוא\u0004 — הרי זה \u0003מעל.\u0004 הרי איפוא שיש דין מעילה בקדשי מזבח! ומתרצים באותו אופן: אף כאן דין המעילה הוא \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006","ושואלים: \u0003ומדאורייתא\u0004 \u0005[ומדברי תורה]\u0006 \u0003לא,\u0004 האם אין דין מעילה בקדשי מזבח? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 לשון הריבוי \"כל\" שנאמרה בכתוב \u0003\"כל חלב לה' \"\u0004(שם ג, טז) — באה \u0003לרבות\u0004 אף את \u0003אימורי קדשים קלים למעילה,\u0004 הרי שהמקור לדין מעילה בקדשי מזבח הוא מן התורה!","ומשיבים: אף זה אינו אלא \u0003מדרבנן\u0004 \u0005[מדברי סופרים].\u0006 ותוהים: \u0003והא קרא קא נסיב לה\u0004 \u0005[והרי מקרא הוא,\u0006 רבי, \u0005מביא לה,\u0006 להלכה זו\u0005]\u0006 להוכיח את דבריו! ומשיבים: ההלכה אינה אלא מדרבנן, והפסוק הוא \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד]\u0006 לדבריהם.","ומקשים על כך: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר עולא, אמר ר' יוחנן: קדשים שמתו\u0004 — \u0003יצאו מידי מעילה דבר תורה.\u0004 ונברר עתה: \u0003במאי\u0004 \u0005[במה],\u0006 באלו קדשים מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בקדשי בדק הבית\u0004 שמתו — יש לשאול: מדוע יצאו מידי מעילה, \u0003אפילו כי\u0004 \u0005[כאשר]\u0006 \u0003מתו נמי\u0004 \u0005[גם כן]\u0006 יהא בהם דין מעילה, שהרי \u0003לא יהא\u0004 הדבר \u0003אלא\u0004 כמי \u0003דאקדיש\u0004 \u0005[שהקדיש]\u0006 \u0003אשפה\u0004 (מקום הנחת זבל) \u0003לבדק הבית,\u0004 וכי \u0003לאו אית\u0004 \u0005[אין]\u0006 \u0003בה מעילה?\u0004","\u0003אלא\u0004 צריך לומר שמדובר ב\u0003קדשי מזבח\u0004 שמתו, ומשמע שבמותם יצאו מדין מעילה מהתורה, ומכאן שבחייהם יש בהם מעילה מדין \u0003דאורייתא\u0004 \u0005[תורה]!\u0006 וקשה: ולדעת ר' ינאי \u0003מי אית בהו\u0004 \u0005[האם יש בהם]\u0006 דין \u0003מעילה\u0004 מן התורה? והלא לדעתו בכל קדשי קדשים פרט לעולה אין דין מעילה!","\u0003אלא\u0004 יש לדחות את מה שאמרנו עד כה, ולומר שאף ר' ינאי סבור כי יש דין מעילה מן התורה בקדשי מזבח, ו\u0003הכי קא אמרי דבי\u0004 \u0005[כך אומרים\u0006 חכמי \u0005בית\u0006 המדרש\u0005] של\u0006 \u0003ר' ינאי\u0004 בנוסח דבריו אלה: \u0003מהאי קרא\u0004 \u0005[מפסוק זה]\u0006 של \"נפש כי תמעול מעל מקדשי ה' \" וגו' דין מעילה ב\u0003קדשי בדק הבית שמעין מינה\u0004 \u0005[שומעים,\u0006 למדים \u0005אנו ממנה],\u0006 ואילו דין מעילה ב\u0003קדשי מזבח\u0004 (פרט לעולה) \u0003לא שמעין מינה\u0004 \u0005[אין אנו שומעים,\u0006 למדים \u0005ממנה],\u0006 שכן, כאמור, אין הם בכלל \"קדשי ה' \" ונזקקים אנו למקרא אחר כדי ללמוד זאת."],["\u0003חמשה דברים\u0004 יש \u0003ב\u0004קרבן ה\u0003עולה\u0004 ובמנחה ובנסכים הבאים עמו שהם \u0003מצטרפין זה עם זה\u0004 לשיעור מעילה, שאם נהנה מהם בשוה פרוטה — הרי זו מעילה. וכן לאיסור אכילת פיגול, נותר וטמא, שאם אכל כזית מכמה מהם — הריהו חייב. וכן אם העלה מכמה מהם שיעור כזית מחוץ למקדש — הריהו חייב משום מעלה בחוץ. ואלו הם: \u0003הבשר והחלב\u0004 של קרבן העולה, הקרבים על המזבח; \u0003והסולת\u0004 של המנחה הבאה עם קרבן העולה; \u0003והיין\u0004 של הנסכים הבאים עם העולה; \u0003והשמן\u0004 של מנחת העולה. \u0003וששה\u0004 דברים מצטרפים בקרבן \u0003תודה\u0004 לשיעור המחייב בפיגול נותר וטמא, ואלו הם: \u0003הבשר, והחלב, והסולת, והיין, והשמן, ו\u0004כן \u0003הלחם\u0004 הבא עם קרבן התודה.","\u0003מתני ליה\u0004 \u0005[היה שונה לו]\u0006 \u0003רב הונא לרבא\u0004 את משנתנו בלשון זו: \u0003\"חמשה דברים בעולם\u0004 (בכלל) \u0003מצטרפין זה עם זה\". אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003\"בעולם\" קא אמרת\u0004 \u0005[אתה אומר],\u0006 והעולה מכך שאין אלא חמישה דברים המצטרפים זה עם זה, \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 התנא בהמשך המשנה \u0003ב\u0004ענין ה\u0003תודה\u0004 כי יש \u0003ששה דברים שבתודה\u0004 המצטרפים זה עם זה, והם \u0003הבשר והחלב והסולת והיין והשמן ולחמי תודה! אמר ליה\u0004 \u0005[לו]\u0006 רב הונא לרבא: \u0003תני\u0004 \u0005[שנה]\u0006 במשנתנו \"חמשה דברים \u0003בעולה\"\u0004 ולא \"חמשה דברים בעולם\".","שנינו במשנתנו כי הבשר והחלב מצטרפים זה עם זה. ומעירים: \u0003תנינא\u0004 \u0005[שנינו]\u0006 איפוא במשנה \u0003להא דתנו רבנן\u0004 \u0005[את זו ששנו חכמים]\u0006 בברייתא: בשר \u0003עולות ואימורים\u0004 \u0003מצטרפין ל\u0004שיעור \u0003כזית\u0004 לאיסור \u0003להעלותן בחוץ\u0004 למקדש, \u0003ולחייב עליהן משום פיגול ונותר וטמא.\u0004","ויש לדייק בדברים: \u0003קתני\u0004 \u0005[שונה]\u0006 החכם בברייתא זו \"עולה ואימורים\", ללמדנו כי \u0003בעולה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נוהג דין צירוף בשר ואימורים, ואולם \u0003בשלמים\u0004 — \u0003לא.\u0004 ונדון בדבר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לחייב משום \u0003להעלותן בחוץ,\u0004 יש מקום להבדיל בין העולה והשלמים, ולומר כי רק ב\u0003עולה\u0004 ש\u0003כליל היא,\u0004 שכולה, בשרה ואימוריה, קרבה על המזבח — \u0003מצטרפין\u0004 בשרה ואימוריה. ואולם \u0003שלמים\u0004 שרק האימורים קרבים — \u0003לא מצטרפין\u0004 הבשר והאימורים. \u0003אלא לחייב עליהן\u0004 את האוכל משניהם כדי שיעור שלם \u0003משום פיגול ונותר וטמא,\u0004 ב\u0003שלמים אמאי לא מחייב\u0004 \u0005[מדוע אינו מתחייב]?\u0006","\u0003והתנן\u0004 \u0005[והרי שנינו]\u0006 במשנה הבאה כי \u0003כל הפיגולים\u0004 מכל סוגי הקרבנות \u0003מצטרפין זה עם זה, וכל הנותרות\u0004 מכל הקרבנות \u0003מצטרפות זו עם זו,\u0004 ובכלל זה אף הבשר והאימורים של שאר הקרבנות, ולא רק של עולה. ומעתה תיקשה הברייתא המחייבת בצירוף הבשר והאימורים רק בקרבן העולה!","ומשיבים: \u0003אלא\u0004 יש לגרוס באופן שונה את דברי הברייתא, וכך \u0003אימא\u0004 \u0005[אמור]\u0006 בה: \u0003עולה ואימוריה מצטרפין זה עם זה ל\u0004שיעור \u0003כזית\u0004 לענין \u0003ליזרק עליהן את הדם.\u0004 שאם לאחר שנשחטה העולה אבד בשרה, ולא נשאר ממנו שיעור כזית אלא בצירוף האימורים, מצטרפים הם להתיר את זריקת דם עולה זו.","\u0003וכיון\u0004 שמצטרפין הבשר והאימורים של העולה לענין \u0003ליזרק את הדם\u0004 — \u0003חייב\u0004 האוכל בצירוף לכדי שיעור המחייב גם משום פיגול נותר וטמא. ואולם בשלמים, שאין מצטרפים הבשר והאימורים — לא נפסלו בפיגול נותר וטמא, ואין האוכלם חייב אף שיש באכילתו משניהם כדי שיעור.","\u0003ומאן קתני לה\u0004 \u0005[ומי\u0006 התנא ש\u0005שונה אותה\u0006 ברייתא\u0005]?\u0006 — \u0003ר' יהושע היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהושע אומר: כל הזבחים שבתורה\u0004 (פרט לקרבן עולה) \u0003ש\u0004אבדו ו\u0003נשתייר מהן כזית בשר\u0004 או \u0003כזית חלב\u0004 — \u0003זורק\u0004 הכהן \u0003את הדם\u0004 עליהם. ואולם אם נשאר מהקרבן שאבד \u0003כחצי זית בשר וכחצי זית חלב\u0004 — \u0003אינו זורק\u0004 עליהם \u0003את הדם,\u0004 שאין הבשר והאימורים מצטרפים לכדי שיעור להתיר את הזריקה, לפי שאין דינם שווה, שהבשר נאכל ואילו האימורים קרבים.","\u0003ו\u0004אילו \u0003בעולה\u0004 שאבדה, \u0003אפילו\u0004 נשתייר ממנה \u0003כחצי זית בשר וכחצי זית חלב\u0004 — \u0003זורק\u0004 עליהם \u0003את הדם.\u0004 וטעם הדבר: \u0003מפני שכולה\u0004 עולה \u0003כליל\u0004 למזבח. \u0003ובמנחה, אפילו כולה קיימת\u0004 — \u0003לא יזרוק\u0004 את הדם.","ותוהים: \u0003מנחה מאי עבידתיה\u0004 \u0005[מה מעשיה\u0006 כאן\u0005],\u0006 הרי אין המנחה טעונה זריקת דם! \u0003אמר רב פפא:\u0004 הכוונה היא ל\u0003מנחת נסכים, כלומר, למנחה הבאה עם הקרבן, וללמדנו שאם הקרבן כולו אבד ונשארו רק הדם ומנחת נסכים שלו — אין זורקים עליה את הדם, ואפילו כולה קיימת, שכן אין היא עצם הקרבן.\u0004","ועוד בענין צירוף לכדי שיעור אחד: \u0003התרומה\u0004 (תרומה גדולה הניתנת לכהן), \u0003ותרומת מעשר\u0004 הניתנת לכהן מתוך המעשר הראשון שקיבל הלוי (מעשר מן המעשר), \u0003ו\u0004כן \u0003תרומת מעשר של\u0004 תבואה שהיא \u0003דמאי\u0004 (ספק מעושרת), \u0003והחלה\u0004 המופרשת מן העיסה, \u0003והביכורים\u0004 (הפירות הראשונים שבשבעת המינים שהשתבחה בהם הארץ, המובאים לבית המקדש וניתנים לכהן) — כל אלה \u0003מצטרפין זה עם זה\u0004 לכלל השיעור שיש בו כדי \u0003לאסור\u0004 את החולין שנתערבו בו. \u0003ו\u0004כן מצטרפים הם לכלל שיעור כזית, \u0003לחייב עליהן\u0004 אם אכלם זר בשגגה \u0003את\u0004 תשלום \u0003החומש\u0004 (חמישית), בנוסף על תשלום הקרן. ועוד בדין הצירוף: \u0003כל הפיגולים\u0004 (הקרבנות שחשב הכהן בשעת עבודתם לאוכלם לאחר זמנם הראוי), אף שהם קרבנות שונים, הריהם \u0003מצטרפין זה עם זה\u0004 לשיעור כזית לחייב את האוכל מהם בעונש כרת (אם אכל במזיד) או בהבאת קרבן חטאת (אם אכל בשוגג). \u0003וכל הנותרים\u0004 (בשר הקרבנות שנותר לאחר הזמן הראוי לאכילתו) מכל מיני קרבנות \u0003מצטרפין זה עם זה\u0004 לאיסור אכילה ולענוש את האוכל.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מצטרפים כל אלה ששנינו בתחילת המשנה? ומשיבים: שכן יש דבר משותף לכולם, שכן \u0003כולהו איקרו\u0004 \u0005[כולם נקראים]\u0006 בכתוב בשם \u0003\"תרומה\".\u0004 ומפרטים: \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003חלה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ראשית ערסתכם חלה תרימו תרומה\"\u0004 (במדבר טו, כ).","\u0003גבי\u0004 \u0005[אצל]\u0006 \u0003ביכורים נמי איקרו\u0004 \u0005[גם כן נקראים]\u0006 הם בכתוב \u0003\"תרומה\", דתניא\u0004 \u0005[ש\u0006כן \u0003שנויה\u0004 ברייתא\u0005]:\u0006 מה שנאמר בכתוב \u0003\"ותרומת ידך\"\u0004 (דברים יב, יז) — \u0003אלו ביכורים. אבל אינך לא צריכא\u0004 \u0005[האחרים,\u0006 תרומה גדולה ותרומת מעשר, \u0005אינם צריכים]\u0006 שיוסבר מדוע מצטרפים הם, ואין צורך להביא כתוב המלמדנו שנקראים הם \"תרומה\", שהרי זהו עצם שמם.","ועוד בענין צירוף: \u0003כל הנבילות\u0004 (הבהמות המתות, שדינן שהן אסורות באכילה ומטמאות במגע ובמשא), הריהן \u0003מצטרפין זו עם זו\u0004 לשיעור כזית. \u0003וכל השקצים\u0004 (השרצים) שאינם מנויים בתורה \u0003מצטרפין זה עם זה\u0004 לכזית לחייב את האוכלם מלקות. ושמונת השרצים המנויים בתורה מצטרפים זה עם זה לשיעור כעדשה לטמא במגע ובמשא ולחייב את האוכלם מלקות.","שנינו במשנתנו כי כל הנבילות מצטרפות זו עם זו, ובענין זה \u0003אמר רב:\u0004"],["\u0003לא שנו\u0004 במשנתנו שנבלת בהמה טמאה מצטרפת לנבלת בהמה טהורה לשיעור אחד של כזית, \u0003אלא לענין\u0004 ה\u0003טומאה\u0004 בלבד. \u0003אבל לענין\u0004 איסור \u0003אכילה\u0004 — נבלותיהם של בעלי חיים \u0003טהורין\u0004 מצטרפים \u0003בפני עצמן,\u0004 \u0003וטמאים בפני עצמן,\u0004 שאין הטהורים מצטרפים עם הטמאים. \u0003ולוי אמר: אפילו לאכילה נמי\u0004 \u0005[גם כן]\u0006 \u0003מצטרפין\u0004 הטמאים עם הטהורים.","\u0003ורב אסי אמר:\u0004 אין מצטרפות אלא נבלות של \u0003טהורים לעצמן ו\u0004של \u0003טמאין לעצמן.\u0004 כיון שלא פירש רב אסי לענין מה אמר את דבריו, אם לענין איסור אכילה בלבד, או לענין הטומאה, נחלקו חכמים בהבנת דבריו. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכוונתו שאין מצטרפות בין לאכילה ובין לטומאה, ונמצא כי \u0003פליגא\u0004 \u0005[חולקת]\u0006 שיטתו זו על שיטת \u0003רב\u0004 הסבור שלענין טומאה מצטרפות אף הטמאות והטהורות. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שרק לענין אכילה אין מצטרפות, אבל לענין הטומאה מצטרפות הטמאות והטהורות, ונמצא כי \u0003לא פליגא\u0004 \u0005[לא חלוקה]\u0006 שיטתו על שיטת רב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת רב אסי ממה ששנינו בברייתא: חצי זית הבא מ\u0003מיתת\u0004 (נבלת) ה\u0003פרה\u0004 (חצי זית מבשר נבלת בהמה טהורה), \u0003ו\u0004חצי זית הבא מ\u0003חיי\u0004 (גופו החי) של ה\u0003גמל\u0004 (חצי זית מבשר בהמה טמאה) — \u0003אין מצטרפין זה עם זה\u0004 לחייבו מלקות על אכילת כזית איסור. ונדייק מכאן: דווקא איסור נבלה טהורה ואיסור טמאה חיה אין מצטרפים, הא \u0005[הרי]\u0006 מ\u0003מיתת\u0004 (נבלת) שניהם, שאכל חצי זית מנבלת פרה וחצי זית מנבלת גמל — הרי אלו \u0003מצטרפין,\u0004 \u0003וקשיא\u0004 \u0005[וקשה]\u0006 \u0003לרב אסי,\u0004 לשיטה המסבירה את דבריו (כשיטת רב) שרק לענין הטומאה הם מצטרפים, אבל לענין האכילה אין מצטרפים! ודוחים: \u0003אימא\u0004 \u0005[אמור,\u0006 דייק\u0005]\u0006 בלשון ברייתא זו, לא כדרך שדייקת, אלא בדרך זו דווקא שני חצאי זיתים ממיתת פרה וחיי גמל אין מצטרפים,","\u0003הא\u0004 \u0005[הרי]\u0006 אם היו שני חצאי הזיתים באים מ\u0003חיי שניהם\u0004 — הרי אלו מצטרפין ללקות על איסור אכילת בשר הבא מן החי. \u0003ומני\u0004 \u0005[ו\u0006כדעת \u0005מי היא]\u0006 שיטת ברייתא זו? — דעת \u0003ר' יהודה היא,\u0004 ש\u0003אמר:\u0004 איסור אכילת \u0003אבר מן החי נוהג\u0004 גם \u0003ב\u0004בהמה \u0003טמאה.\u0004","ושואלים על תירוץ זה: \u0003אבל\u0004 באשר לצירוף שני חצאי זיתים הבאים מ\u0003מיתת שניהם, מאי\u0004 \u0005[מה]\u0006 יהא הדין? אם נאמר ש\u0003לא מצטרפי\u0004 \u0005[מצטרפים]\u0006 — \u0003אם כן, מאי איריא דרהיט ותני\u0004 \u0005[מה שייך, שרץ,\u0006 הרחיק התנא \u0005ושנה]\u0006 אופן זה של צירוף \u0003מיתת פרה וחיי גמל\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אפילו\u0004 באכילת שני חצאי זיתים מ\u0003מיתת שניהם\u0004 \u0003לא מצטרפי\u0004 \u0005[אינם מצטרפים]!\u0006","\u0003ועוד,\u0004 הרי \u0003תניא\u0004 \u0005[שנויה]\u0006 ברייתא אחרת: \u0003חצי זית\u0004 הבא מ\u0003פרה בחייה וחצי זית\u0004 הבא מ\u0003גמל במיתתה\u0004 — \u0003אין מצטרפין. אבל חצי זית\u0004 הבא \u0003מפרה וחצי זית\u0004 הבא \u0003מגמל, בין בחייה בין במיתתה\u0004 — \u0003מצטרפין.\u0004 ולכאורה \u0003קשיא רישא\u0004 \u0005[קשה התחלת]\u0006 הברייתא האומרת שאין חצי זית פרה בחייה מצטרף לחצי זית גמל במיתתו \u0003אסיפא\u0004 \u0005[על סוף]\u0006 הברייתא ממנו משמע שאינם מצטרפים! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שכוונת סוף הברייתא היא ששני חצאי זיתים הבאים מ\u0003מיתת שניהם,\u0004 או שני חצאי זיתים הבאים מחיי שניהם — \u0003מצטרפין\u0004 ללקות על אכילת איסור, וקשה איפוא על שיטת רב אסי!","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול \u0005לומר,\u0006 להשיב] \u0003לך רב אסי: האי\u0004 \u0005[זה]\u0006 ה\u0003תנא\u0004 של ברייתא זו \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003איסור חל על איסור,\u0004 ואף איסור אכילת נבילה חל על איסור אכילת בשר בהמה טמאה, ומשום כך מצטרפים שני חצאי זיתים אלה לכלל זית האסור באכילה, ולוקים על אכילתו. אבל רב אסי עצמו סבור שאין איסור חל על איסור ולכן אין זו קושיה על דבריו, שכן לדבריו אכן אינם מצטרפים."],["\u0003אמר רב יהודה, אמר רב:\u0004 על \u0003אכילת שרצים לוקה עליו\u0004 כאשר אכל \u0003כזית. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 — שכן לשון \u0003'אכילה' כתיב בהו\u0004 \u0005[נאמר בהם],\u0006 שכך נאמר בשרצים: \"כל הולך על גחון וכל הולך על ארבע עד כל מרבה רגלים לכל השרץ השורץ על הארץ לא תאכלום כי שקץ הם\" (ויקרא יא, מב), וכלל הוא שסתם אכילה שיעורה בכזית.","ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' יוסי בר ר' חנינא קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא על הכתוב \u0003\"והבדלתם בין הבהמה הטהרה לטמאה ובין העוף הטמא לטהר ולא תשקצו את נפשתיכם בבהמה ובעוף ובכל אשר תרמש האדמה אשר הבדלתי לכם לטמא\"\u0004 (ויקרא כ, כה), שיש בכתוב זה שני עניינים, שהרי \u0003פתח הכתוב ב\u0004ענין איסור \u0003אכילה\u0004 (\"ולא תשקצו את נפשותיכם\"), \u0003וסיים ב\u0004ענין ה\u0003טומאה\u0004 (\"אשר הבדלתי לכם לטמא\").","ללמד: \u0003מה טומאה\u0004 של שרצים היא \u0003ב\u0004שיעור \u0003כעדשה, אף\u0004 שיעור המחייב ב\u0003אכילה\u0004 הריהו \u0003בכעדשה. וקלסיה\u0004 \u0005[ושיבח אותו]\u0006 \u0003ר' יוחנן\u0004 על דבריו, \u0003וקשיא\u0004 \u0005[וקשה] ל\u0006שיטת \u0003רב\u0004 האומר שלוקים על אכילת שרצים רק בשיעור כזית!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003כאן\u0004 (בברייתא) מדובר באכילת שרצים \u0003במיתתן\u0004 (לאחר שמתו), והריהו לוקה על שיעור כעדשה, ששיעור טומאתם ושיעור אכילתם שווים ולכך אף רב מודה. ואילו \u0003כאן\u0004 (בדברי רב) מדובר באכילת שרצים \u0003בחייהן,\u0004 כשאינם מטמאים, ואז שיעור אכילתם כשאר איסורי אכילה, בכזית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף בשאלה על תירוץ זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב אמתניתין קאי\u0004 \u0005[על משנתנו עומד,\u0006 מתייחס\u0005],\u0006 בדבריו אלה, \u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 בלשון \u0003\"כל השרצים\"\u0004 \u0003קתני\u0004 \u0005[היא שונה],\u0006 לומר שהדברים אמורים בכל האופנים בהם אסורים השרצים באכילה, בחייהם ו\u0003אפילו במיתתן. לאו\u0004 \u0005[האם לא]\u0006 מדובר במשנתנו, שמצטרפים הם זה לזה לשיעור המחייב, גם \u0003דאיכא פורתא מהאי ופורתא מהאי\u0004 \u0005[שיש קצת מזה,\u0006 שרצים חיים, \u0005וקצת מזה,\u0006 שרצים מתים\u0005]?\u0006 הרי איפוא שרב אמר את דבריו, שחיוב אכילה בשרצים הוא בשיעור כזית, אף בשרצים שמתו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 לאביי בדחיית שאלתו זו: \u0003ההיא דיוקא\u0004 \u0005[דיוק זה]\u0006 שאתה מדייק \u0003דילך\u0004 \u0005[שלך]\u0006 \u0003הוא,\u0004 ואתה הוא שמקשר את דברי רב למשנה ומסיק ממנו מסקנות. ואולם הנכון הוא כי \u0003רב\u0004 — \u0003שמעתא בעלמא קאמר\u0004 \u0005[הלכה בכלל הוא אומר]\u0006 שאינה מתייחסת למשנה.","בשנינו קודם כי \u0003קלסיה\u0004 \u0005[שבח אותו]\u0006 ר' יוחנן את ר' יוסי בר ר' יהודה על הברייתא שהביא ועל דיוק דבריו בברייתא זו. הרי שר' יוחנן סבור כי השיעור על אכילת שרצים טמאים הוא בכעדשה. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו במשנה במסכת אהלות: \u0003האיברין\u0004 השלמים (שיש בהם בשר, גידים ועצמות) הבאים מן המטמאים (המת, נבלה, השרץ) — \u0003אין להן שיעור\u0004 לטומאתם, ו\u0003אפילו\u0004 אבר בשיעור ה\u0003פחות מכזית\u0004 מה \u0003נבלה ו\u0004אבר בשיעור ה\u0003פחות מכעדשה מן השרץ\u0004 — הריהם \u0003מטמאין. ואמר ר' יוחנן:\u0004 כך הוא דינם לענין הטומאה, ואולם לענין שיעור אכילה, \u0003אין לוקין עליהן אלא בכזית.\u0004 הרי שלדעת ר' יוחנן אין לוקים על אכילת שרצים בכעדשה!","\u0003אמר רבא\u0004 בתירוץ הקושיה: שיטת ר' יוחנן שלוקים על אכילת שרצים אף בשיעור כעדשה אינה אלא \u0003ב\u0004שרצים ה\u0003מובדלין\u0004 (הנבדלים משאר השרצים), והם שמונת השרצים המטמאים במותם שבהם \u0003דבר הכתוב\u0004 (\"וזה לכם הטמא בשרץ השורץ על הארץ החולד והעכבר והצב למינהו. והאנקה והכח והלטאה והחומט והתנשמת. אלה הטמאים לכם בכל השרץ כל הנוגע בהם במותם יטמא עד הערב\" (ויקרא יא, כט—לב). ועל שרצים אלה בלבד מדובר בברייתא. ואילו בשאר השרצים סבור ר' יוחנן ששיעור אכילתם המחייב הוא (כבשאר איסורי אכילה) בכזית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא\u0004 בדחיית תירוצו: \u0003אלא מעתה\u0004 לדבריך אלה שקיים הבדל בשיעורי אכילה בין השרצים המובדלים לבין שאר השרצים, אם כן בטומאת \u0003בהמה נמי\u0004 \u0005[גם כן],\u0006 \u0003ליפלגי\u0004 \u0005[שיחלקו]\u0006 \u0003בין\u0004 זו ה\u0003מובדלת\u0004 (נבלת בהמה טהורה) ששיעור טומאתה הוא בכזית \u0003ל\u0004בין זו \u0003שאינה מובדלת\u0004 (נבלת בהמה טמאה) ששיעור טומאתה הריהו יותר מכזית, בכביצה."],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כי קא מקיש רחמנא\u0004 \u0005[כאשר משוה הכתוב]\u0006 בהמה טמאה ובהמה טהורה לשרצים הרי זה רק \u0003ל\u0004ענין איסור \u0003\"בל תשקצו\u0004 את נפשותיכם\" (ראה ויקרא כ, כה), ללמדנו שחייב האוכל את אלה גם משום האיסור הכללי \"בל תשקצו\", \u0003אבל ל\u0004ענין ההבחנה ב\u0003שיעורין\u0004 בין הבהמה המובדלת לבין זו שאינה מובדלת — \u0003לא\u0004 הוקשו הבהמות לשרצים.","\u0003דם השרץ\u0004 משמונת השרצים המטמאים במותם \u0003והבשר\u0004 שלו \u0003מצטרפין זה עם זה\u0004 לשיעור טומאה, שהוא בכעדשה. \u0003כלל אמר ר' יהושע: כל שטומאתו\u0004 (דרגת הטומאה וכן דין הטומאה, טומאת ערב או שבעה) \u0003ושיעורו\u0004 לטמא \u0003שוין\u0004 זה לזה (וכגון שני חצאי זיתים הבאים משני מתים, או משתי נבילות, או שני חצאי עדשה הבאים משני שרצים) — \u0003מצטרפין\u0004 זה לזה.","\u0003טומאתו ולא שיעורו,\u0004 כגון שרץ ונבילה שטומאתם שווה, שבשניהם יש טומאת ערב, ואולם אין שיעורם שווה, ששיעור הנבילה לטמא — בכזית, ושיעור השרץ לטמא — בכעדשה, או ש\u0003שיעורו\u0004 שווה \u0003ולא טומאתו,\u0004 וכגון מת ונבילה, ששניהם מטמאים בכזית, ואולם לנבילה — טומאת ערב, ולמת — טומאת שבעה. וכל שכן כאשר הם אינם שווים \u0003לא\u0004 ב\u0003טומאתו\u0004 ולא (ראה גרסות) ב\u0003שיעורו\u0004 — \u0003אין\u0004 הם \u0003מצטרפין\u0004 זה לזה לטמא.","שנינו במשנתנו כי דם השרץ מצטרף לבשרו, ובהסבר הדברים \u0003אמר רב חנין, אמר רב זעירא: ו\u0004בלבד שיהא הדם","\u0003[בו] (וכן)\u0004 (ראה גרסות ועיונים), בשרץ עצמו, ולא שפרש ממנו. \u0003אמר ר' יוסי בר ר' חנינא\u0004 בקושיה: והרי שנינו בברייתא על הכתוב בפרשת המאכלים האסורים \"אלה \u0003הטמאים\u0004 לכם בכל השרץ\" (ויקרא יא, לא), ולשון הריבוי \"הטמאים\" \u0003מלמד שהן מצטרפין\u0004 לטמא, \u0003ואפילו\u0004 בשר \u0003שרץ\u0004 זה \u0003ו\u0004בשר \u0003שרץ\u0004 אחר, ואפילו בשר \u0003שרץ ודם\u0004 השרץ. \u0003בין\u0004 שהם באים \u0003משם אחד,\u0004 ממין אחד של שרץ, ו\u0003בין\u0004 שהם באים \u0003משני שמות,\u0004 כגון העכבר והחולד. הרי איפוא שדם של שרץ אחד מצטרף לבשר שרץ אחר, ואין צריך שיהיה הדם בשרץ עצמו!","\u0003אמר רב יוסף\u0004 בתירוץ קושיה זו: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 (בברייתא) מדובר שהדבר הנטמא נגע \u0003בכולו,\u0004 בחצי שיעור דם הבא משרץ שלם אחד וכן בחצי שיעור בשר הבא משרץ שלם אחר, שכיון שהם באים מדבר חשוב הריהם מצטרפים לכדי שיעור אחד. ואילו \u0003כאן\u0004 (בדברי רב זעירא) מדובר שנגע רק \u0003במקצתו,\u0004 כלומר, בחצי שיעור דם הבא משרץ אחד שאינו שלם וכן בחצי שיעור בשר הבא משרץ אחר שאינו שלם, ובאופן זה — אין הדם מצטרף לבשר השרץ.","ומסבירים את ההבחנה הזו, \u0003ומנא תימרא\u0004 \u0005[ומנין אתה אומר,\u0006 לומד\u0005]\u0006 הבחנה זו בין הנוגע כולו למקצתו? \u0003מדתניא\u0004 \u0005[מ\u0006מה ששנויה ברייתא\u0005]:\u0006 \u0003נשפך\u0004 דם המת בשיעור המטמא, שהוא כרביעית הלוג \u0003על הרצפה\u0004 של הבית, והיה מקומה קטפרס (מדרון), שהדם נוזל בו, אם \u0003איהל\u0004 (האהיל) אדם \u0003על מקצתו\u0004 — הריהו \u0003טהור,\u0004 שכן אין הדם הנוזל בקטפרס נחשב כיחידה אחת, ונמצא שלא האהיל על כל רביעית הדם המת. \u0003איהל על כולו,\u0004 על כל רביעית הדם — הריהו \u0003טמא.\u0004","ויש לשאול: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \"איהל על \u0003מקצתו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה היא שהאהיל על \u0003מקצת\u0004 מרביעית \u0003דם,\u0004 כלומר, שלא נשפכה על הרצפה רביעית דם אלא פחות מכך, ו\"איהל על כולו\" הכוונה — שהאהיל על רביעית שלימה — \u0003והא\u0004 \u0005[והלא]\u0006 אי אפשר לומר כך, שהרי \u0003אמר ר' חנינא, אמר רבי: רביעית דם שהגיס\u0004 (בחש) \u0003בה\u0004 אדם בכלי, באופן שלא נטמא בכך בטומאת מגע — \u0003טהורה,\u0004 אין כאן טומאת אהל, אף שבקדירה שהגיס בה היתה רביעית דם ובודאי האהיל על כולה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[תלמד מכאן]\u0006 שההבחנה בין \"כולו\" ל\"מקצתו\" אינה בין רביעית שלימה לחלק מרביעית, אלא בין הבאה משרץ או מת שלם לבאה מחלק ממנו. ואף כדי להסביר את ההבדל בין דברי ר' זעירא לברייתא, יש לחלק ולומר כדברי ר' יוסף כי \u0003כאן\u0004 בברייתא מדובר באופן שנגע \u0003בכולו,\u0004 כלומר, בבאים משרץ שלם, ואילו \u0003כאן\u0004 בדברי ר' זעירא מדובר באופן שנגע רק \u0003במקצתו,\u0004 כלומר, בבאים משרץ שאינו שלם. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","מסופר, \u0003שאל ר' מתיא בן חרש את ר' שמעון בן יוחאי\u0004 בהיותו בעיר רומי: מנין לדם שרצים שהוא טמא? אמר לו: שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין איסור אכילת השרצים \u0003\"וזה לכם הטמא\"\u0004 (ויקרא יא, כט), ולמדים זאת מיתור הכתוב, שהרי כבר נאמר בדומה \"אלה הטמאים לכם\" (שם פסוק לא).","\u0003אמרו לו תלמידיו\u0004 של ר' מתיא בן חרש לרבם בהתפעלות: כמה \u0003חכים ליה\u0004 \u0005[החכים לו]\u0006 \u0003בן יוחאי\u0004 שדרש דרשה זו. \u0003אמר להם:\u0004 אין זו דרשתו של ר' שמעון בן יוחאי, אלא הרי זה \u0003תלמוד ערוך\u0004 (לימוד ברור ומסודר) \u0003בפיו של ר' אלעזר בר ר' יוסי,\u0004 וממנו למד ר' שמעון בן יוחאי. ואימתי היה דבר זה? \u0003שפעם אחת גזרה המלכות\u0004 (השלטון הרומאי) \u0003גזרה\u0004 (שלש גזירות) על בני ישראל: \u0003שלא ישמרו את השבת; ושלא ימולו את בניהם; וש\u0004לא תטבולנה בנות ישראל מטומאת נדתן, ובכך יבואו בני ישראל ו\u0003יבעלו את\u0004 נשותיהן ה\u0003נדות.\u0004","\u0003הלך ר' ראובן בן איסטרובלי, ו\u0004על מנת שלא יכירו בו שהוא יהודי \u0003סיפר\u0004 (הסתפר) תספורת המכונה \u0003קומי,\u0004 הרווחת בין הגויים ואין בני ישראל מסתפרים כך, \u0003והלך וישב עמהם\u0004 בשעה שדנו בשלש גזירות אלה. \u0003אמר להם: מי שיש לו אויב,\u0004 מה הוא רוצה, האם שאויבו \u0003יעני\u0004 (יהיה לעני) \u0003או\u0004 ש\u0003יעשיר\u0004 (יהיה לעשיר)? \u0003אמרו לו:\u0004 ש\u0003יעני. אמר להם: אם כן,\u0004 אף בעניינם של היהודים, מוטב ש\u0003לא יעשו\u0004 היהודים \u0003מלאכה בשבת, כדי שיענו\u0004 בכך! \u0003אמרו: טבית\u0004 \u0005[טוב,\u0006 יפה\u0005]\u0006 \u0003אמר\u0004 אדם זה, ולכן ראוי \u0003ליבטל\u0004 \u0005[שתבטל]\u0006 גזירה זו, עמדו \u0003ובטלוה,\u0004 והתירו לבני ישראל שלא לעשות מלאכה בשבת.","\u0003חזר ואמר להם: מי שיש לו אויב,\u0004 מה הוא רוצה, ש\u0003יכחיש\u0004 (ירזה, יחלש) אויבו \u0003או יבריא\u0004 (ישמין, יתחזק)? \u0003אמרו לו:\u0004 ש\u0003יכחיש. אמר להם: אם כן,\u0004 מוטב ש\u0003ימולו\u0004 היהודים את \u0003בניהם לשמונה ימים ויכחישו\u0004 בכך את גופם. \u0003אמרו: טבית\u0004 \u0005[טוב,\u0006 יפה\u0005]\u0006 \u0003אמר, ובטלוה\u0004 \u0005[ובטלו אותה]\u0006 גם את הגזירה הזו.","\u0003חזר ואמר להם: מי שיש לו אויב,\u0004 מה הוא רוצה, האם ש\u0003ירבה\u0004 אויבו \u0003או\u0004 ש\u0003יתמעט? אמרו לו:\u0004 ש\u0003יתמעט.\u0004 אמר להם: \u0003אם כן,\u0004 מוטב ש\u0003לא יבעלו\u0004 בני ישראל את נשותיהן בזמן שהן \u0003נדות,\u0004 ויוולדו להם בכך פחות ילדים, ויתמעט מספרם. \u0003אמרו: טבית\u0004 \u0005[טוב,\u0006 יפה\u0005]\u0006 \u0003אמר, ו\u0004אף גזירה זו \u0003בטלוה.\u0004","לאחר זמן \u0003הכירו בו שהוא יהודי,\u0004 והבינו שטענותיו היו לטובת היהודים, עמדו ו\u0003החזירום\u0004 את כל הגזירות האלה למקורן. באותה עת \u0003אמרו\u0004 חכמים: \u0003מי\u0004 מאתנו \u0003ילך ויבטל\u0004 את \u0003הגזרות\u0004 הללו?"],["מוטב ש\u0003ילך\u0004 לרומי \u0003ר' שמעון בן יוחאי, ש\u0004כן \u0003הוא מלומד\u0004 (רגיל) \u0003בנסים\u0004 \u0003ואחריו\u0004 (ובנספח לו) \u0003מי\u0004 מחכמי ישראל \u0003ילך?\u0004 — \u0003ר' אלעזר בר ר' יוסי.\u0004","כששמע זאת ר' יוסי, אביו של ר' אלעזר, \u0003אמר להם ר' יוסי: ואילו היה אבא\u0004 (אבי) החכם \u0003חלפתא קיים\u0004 (חי) האם \u0003יכולין אתם\u0004 (הייתם) \u0003לומר לו: תן\u0004 (מסור) את \u0003בנך להריגה?\u0004 ואף אתם, כיצד יכולים לבקש ממני שאשלח את בני לשליחות מסוכנת כזו? \u0003אמר להם ר' שמעון\u0004 לחכמים: והרי כמו כן \u0003אילו היה יוחאי אבא קיים,\u0004 האם \u0003יכולין אתם\u0004 (הייתם) \u0003לומר לו: תן בנך להריגה?\u0004 ובכל זאת, הריני מוכן ללכת לרומי, כן גם ר' אלעזר בנו של ר' יוסי ילך.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' יוסי: אנא אזלין\u0004 \u0005[אני אלך],\u0006 ולא בני, וטעם הדבר שאיני חפץ שבני ילך עם ר' שמעון בן יוחאי, כי בני נער וממהר להשיב ויכול להכעיס את ר' שמעון שכעסן הוא (תוס'), וחושש אני \u0003דלמא עניש ליה\u0004 \u0005[שמא יעניש אותו]\u0006 \u0003ר' שמעון,\u0004 שיקפיד עליו, וזה הדבר \u0003דקא מסתפינא\u0004 \u0005[ש\u0006מפניו \u0005אני מפחד].\u0006 \u0003קביל עליה\u0004 \u0005[קיבל עליו]\u0006 ר' שמעון בן יוחאי ש\u0003לא ליענשיה\u0004 \u0005[יגרום לו\u0006 לר' אלעזר בנו של ר' יוסי \u0005שייענש על ידו].\u0006 ומסופר, כי \u0003אפילו הכי\u0004 \u0005[כך],\u0006 למרות זאת, בסופו של דבר \u0003ענשיה\u0004 \u0005[הענישו]\u0006 ר' שמעון. וכיצד היה הדבר?","\u0003כשהיו מהלכין בדרך\u0004 לרומי, \u0003נשאלה\u0004 באחד המקומות \u0003שאלה זו בפניהם: מנין לדם השרץ שהוא טמא? עקם פיו\u0004 (מלמל בלחישה) \u0003ר' אלעזר בר ר' יוסי\u0004 כדי שלא ישמע ר' שמעון ויכעס שהוא מורה הלכה בפני רבו, \u0003ואמר:\u0004 דבר זה נלמד מהאמור בתורה \u0003\"וזה לכם הטמא\u0004 בשרץ השורץ על הארץ...\", ויקרא יא, כט, ואף שלא רצה ר' אלעזר בר' יוסי שישמע ר' שמעון את דבריו, שמעם ר' שמעון ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון:\u0004 אף ש\u0003מעקימת שפתיך אתה ניכר שתלמיד חכם אתה,\u0004 מכל מקום אין לתלמיד חכם להורות הלכה בפני רבו, ולכן \u0003אל יחזור הבן\u0004 ממסעו זה \u0003אצל אביו.\u0004","ובהמשך הסיפור נמסר כי כשקרבו לרומי \u0003יצא לקראתו\u0004 שד הנקרא \u0003בן תמליון,\u0004 ואמר להם: \u0003רצונכם\u0004 שאצטרף אליכם ו\u0003אבוא עמכם\u0004 לצורך ביטול הגזירות? כשראה ר' שמעון בן יוחאי כי נזדמן לו שד לצורך הצלת בני ישראל \u0003בכה ר' שמעון ואמר:\u0004 ו\u0003מה שפחה של בית אבא,\u0004 הגר המצרית שפחת בית אברהם אבינו, \u0003נזדמן לה מלאך שלש פעמים,\u0004 כאשר ברחה מפני שרי גבירתה. \u0003ואני לא\u0004 ראוי שיזדמן לי מלאך, ואפילו לא \u0003פעם אחת?\u0004 ואולם אף על פי כן, \u0003יבא הנס מכל מקום\u0004 שיבוא.","ומסופר עוד, כי \u0003קדים\u0004 \u0005[קדם]\u0006 \u0003הוא\u0004 אותו השד, לפני בואם של החכמים לרומי, ו\u0003על בברתיה\u0004 \u0005[ונכנס בבתו]\u0006 של ה\u0003קיסר\u0004 ונשתגעה. \u0003כי מטא התם\u0004 \u0005[כאשר הגיע\u0006 ר' שמעון \u0005לשם,\u0006 לארמונו של הקיסר\u0005],\u0006 \u0003אמר: בן תמליון, צא! בן תמליון, צא! וכיון דקרו ליה, נפק אזל\u0004 \u0005[וכיון שקראו לו,\u0006 אכן \u0005יצא\u0006 בן תמליון מגופה של בת הקיסר, ו\u0005הלך],\u0006 ונרפאה בת הקיסר. כיון שראה הקיסר כן, \u0003אמר להון\u0004 \u0005[להם]:\u0006 \u0003שאילו\u0004 \u0005[שאלו,\u0006 בקשו\u0005]\u0006 כשכר על רפואת בתי מתוך אוצרותי \u0003כל מה דאית לכון למישאל\u0004 \u0005[שיש לכם לבקש].\u0006 \u0003ועיילינהו לגנזיה לשקול כל דבעו\u0004 \u0005[והכניסם לגנזיו שיקחו\u0006 משם \u0005כל\u0006 מה \u0005ש\u0006הם \u0005רוצים].\u0006 \u0003אשכחו\u0004 \u0005[מצאו]\u0006 שם את \u0003ההוא איגרא\u0004 \u0005[אותה אגרת,\u0006 צו שלש הגזירות הללו\u0005],\u0006 \u0003שקלוה וקרעוה\u0004 \u0005[לקחוה וקרעוה].\u0006","ומעירים בעקבות סיפור זה: \u0003והיינו\u0004 \u0005[וזהו]\u0006 ההסבר למה שמוצאים אנו במקום אחר ש\u0003אמר ר' אלעזר בר ר' יוסי\u0004 לפני חכמים כי \u0003אני ראיתיה\u0004 (את הפרוכת בית המקדש) בהיותי בבית אוצרותיו של הקיסר \u0003בעיר רומי, והוו עליה כמה טיפי דמים,\u0004 שראה אותה ר' אלעזר כאשר נכנס לבית אוצרותיו של הקיסר.","א משנה \u0003הפיגול\u0004 (זבח שחשב עליו הכהן בשעת עבודתו לאוכלו שלא בזמנו הראוי) \u0003והנותר\u0004 לאחר זמן אכילתו — \u0003אין מצטרפין\u0004 זה לזה. וטעם הדבר, \u0003מפני שהן שני שמות\u0004 איסורים (לאוים) נפרדים. \u0003השרץ והנבלה, וכן הנבלה ובשר המת\u0004 — \u0003אין\u0004 הם \u0003מצטרפין זה עם זה\u0004 לשיעור שיש בו כדי \u0003לטמא.\u0004 ודברים אלה אמורים \u0003אפילו\u0004 לענין צירופם לטמא \u0003ב\u0004טומאה של ה\u0003קל שבשניהן,\u0004 כגון שיצטרף בשר השרץ החמור שאין בו כשיעור טומאה, לבשר הנבילה הקל שאין בו שיעור טומאה, להשלים לשיעור כזית.","\u0003אמר רב יהודה, אמר שמואל: לא שנו\u0004 במשנתנו שאין הפיגול והנותר מצטרפים זה לזה לשיעור שלם \u0003אלא ל\u0004ענין \u0003טומאת הידים\u0004 של הנוגע בפיגול ובנותר, \u0003דמדרבנן\u0004 \u0005[ש\u0006כן \u0005מדברי סופרים]\u0006 \u0003היא\u0004 טומאה זו. \u0003אבל לענין\u0004 חיוב מלקות על \u0003אכילה\u0004 שיעור כזית משניהם גם יחד — הריהם \u0003מצטרפין,\u0004 שכן איסור האכילה הוא מן התורה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר בתורה בדינו של הנותר מן הקדשים \"ושרפת את הנותר באש \u0003לא יאכל כי קדש הוא\"\u0004 (שמות כט, לד), ומובן הכתוב — שכיון שנפסל קודש זה, הריהו באיסור אכילה, ומכאן למדנו כלל לדינם של כל הקדשים שנפסלו בכל דרך כי \u0003כל שבקדש פסול\u0004 (כל קודש שנפסל), \u0003בא הכתוב\u0004 לאוסרו באיסור תורה ו\u0003ליתן לא תעשה על אכילתו.\u0004","\u0003האוכל שנטמא באב הטומאה\u0004 והריהו ראשון לטומאה (ולד הטומאה), והאוכל \u0003שנטמא בולד הטומאה,\u0004 והריהו שני לטומאה — \u0003מצטרפין זה עם זה,\u0004 אם היה כל אחד מהם פחות משיעור כביצה המטמא, לשיעור שלם \u0003לטמא ב\u0004טומאתו של ה\u0003קל שבשניהם,\u0004 כלומר, בטומאת השני לטומאה. \u0003כל האוכלים\u0004 (מאכלים) הטמאים \u0003מצטרפין זה עם זה, לפסול הגוייה\u0004 (גוף האדם) של האוכל מהם, אם אכל מכולם גם יחד בשיעור כבחצי פרס. וכן מצטרפים לשיעור","\u0003כבמזון שתי סעודות\u0004 הנדרש \u0003לעירוב\u0004 תחומין. \u0003ו\u0004כן לשיעור \u0003כביצה לטמא טומאת אוכלין,\u0004 שאין המאכלים הטמאים מטמאים אלא בשיעור זה. \u0003ו\u0004כן לשיעור \u0003כגרוגרת,\u0004 שהוא השיעור המחייב \u0003ל\u0004ענין \u0003הוצאת שבת\u0004 (מרשות לרשות). \u0003ו\u0004כן לשיעור \u0003ככותבת\u0004 (כתמרה) לחיוב האוכל כשיעור זה \u0003ביום הכפורים.\u0004 וכן \u0003כל המשקין\u0004 הטמאים \u0003מצטרפין זו עם זו, לפסול את הגוייה,\u0004 שהאדם השותה \u0003ב\u0004כדי שיעור \u0003רביעית\u0004 (הלוג) מכולם גם יחד בשיעור זה, פסול מעתה לאכול בתרומה עד שייטהר, ופוסל את התרומה במגעו. \u0003ו\u0004להתחייב על שתייה בשיעור \u0003כמלא לוגמא\u0004 (לוגמיו) \u0003ביום הכפורים.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: מה טעם\u0004 מצטרפים הראשון לטומאה עם השני לטומאה? — מפני \u0003שאפשר לשני\u0004 לטומאה \u0003שיעשה ראשון\u0004 לטומאה. ותוהים על כך: \u0003ומי קא עביד\u0004 \u0005[והאם עושה]\u0006 \u0003שני\u0004 לטומאה את שנוגע בו \u0003ראשון\u0004 לטומאה? \u0003הא\u0004 \u0005[הרי]\u0006 דבר זה \u0003לא אפשר!\u0004 שכן הנוגע בשני אינו אלא שלישי!","\u0003אמר רבא, הכי קאמר\u0004 \u0005[כך אמר,\u0006 זו כוונת המשנה\u0005]:\u0006 \u0003מי גרם לשני\u0004 לטומאה? \u0003לאו\u0004 \u0005[האם לא]\u0006 זה ה\u0003ראשון\u0004 לטומאה שטימא אותו?! ולכן, קשורים הם זה לזה, אף לענין שיצטרפו להשלים לשיעור טומאה. \u0003רב אשי אמר\u0004 באופן זה את כוונת המשנה: גם ה\u0003ראשון\u0004 לטומאה \u0003ו\u0004גם ה\u0003שני\u0004 לטומאה, הריהם \u0003לגבי\u0004 (ביחס) ל\u0003שלישי\u0004 לטומאה — \u0003בני חדא ביקתא אינון\u0004 \u0005[בית אחד הם],\u0006 כלומר, שהשני והראשון לטומאה נלמדים מכתוב אחד. ומשום כך מצטרף הראשון לשני."],["\u0003הערלה\u0004 (יבול העץ בשלש השנים הראשונות לנטיעתו) \u0003וכלאי הכרם\u0004 (שזרע בתוך כרם ענבים מיני תבואה) — \u0003מצטרפין זה עם זה\u0004 לשיעור האוסר את התערובת שהוא אחד ממאתים. \u0003ר' שמעון אומר: אין מצטרפין.\u0004","ושואלים: \u0003ומי\u0004 \u0005[האם]\u0006 \u0003צריך\u0004 לשיטת \u0003ר' שמעון\u0004 במשנתנו האומר שאין שני חצאי שיעורים מאיסורים שונים מצטרפים לכדי שיעור, \u0003לצרופי\u0004 \u0005[לצרף]\u0006 שני חצאי שיעורים כדי ללקות? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 האוכל מן האיסור בשיעור \u0003כל שהוא\u0004 די בכך כדי \u0003ל\u0004היענש על כך ב\u0003מכות,\u0004 ולא נאמר דין שיעור אכילה בכזית אלא לענין הבאת קרבן אם אכל בשוגג? ומשיבים: אכן אין לשון משנתנו מדוייקת, וכך \u0003תני\u0004 \u0005[שנה]\u0006 בה: ר' שמעון אומר, \u0003אין צריכין לצרף,\u0004 שכן לוקה הוא אף בפחות מאכילת כזית.","\u0003הבגד\u0004 ששיעורו לקבל טומאה הוא שלוש על שלוש אצבעות, \u0003והשק\u0004 ששיעורו ארבעה על ארבעה טפחים, וכן \u0003השק והעור\u0004 ששיעורם חמישה על חמישה טפחים, \u0003העור והמפץ\u0004 (המחצלת) ששיעור טומאתה בשישה על שישה טפחים — \u0003כולן מצטרפין זה עם זה,\u0004 שאם צירף משנים מהם כשיעור הקל שבהם — הרי הם ראויים לקבל טומאה. \u0003אמר ר' שמעון: מה טעם\u0004 מצרפים אותם למרות שאין שיעוריהם שוים? — \u0003מפני שהן\u0004 כולם \u0003ראוין ליטמא במושב,\u0004 שאם ישב עליהם הזב הרי הוא מטמא אותם, וכיון שלענין טומאת מושב הזב (מדרס) די בשיעור הראוי לאחד מהם כדי להיטמא, הריהם מצטרפים אף לטומאות אחרות.","","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003קיצע\u0004 (קיצץ) \u0003מכולן,\u0004 מאלה המפורטים במשנה, מכל אחד מהם פחות מ\u0003שלשה\u0004 טפחים על שלושה טפחים, \u0003ועשה מהן בגד,\u0004 אם חשב עליו לעשותו \u0003למשכב\u0004 — הרי שיעורו \u0003שלשה\u0004 טפחים, ואם חשב עליו \u0003למושב\u0004 — שיעורו ב\u0003טפח,\u0004 ואם חשב עליו \u0003ל\u0004צורך \u0003אחיזה\u0004 — הרי הוא מטמא ב\u0003כל שהו.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003לאחיזה? אמר ריש לקיש, אמר ר' ינאי: שכן עומד לנוולה\u0004 ( לאריגה בנול), שכן האורגים שמים בד כלשהו על ידיהם בזמן שהם מיישרים את החוטים, על מנת שלא ייחתכו בהם. \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 הסבר אחר: \u0003הואיל וראוי לקוצצי תאנים\u0004 ששמים בד על ידיהם שלא יתלכלכו.","","","","","","","\u0003ה\u0004עובר ו\u0003נהנה מן ההקדש\u0004 הנאה שערכה \u0003שוה פרוטה, אף על פי שלא פגם\u0004 (הפחית את ערך) אותו דבר הקדש — בכל זאת מעל, וחייב כדין המועל, בהבאת קרבן ובתשלום קרן וחומש. אלו \u0003דברי ר' עקיבא. וחכמים אומרים: כל דבר\u0004 הקדש \u0003שיש בו פגם,\u0004 שהשימוש פוגם בו — \u0003לא מעל\u0004 אף שנהנה ממנו, \u0003עד שיפגום\u0004 בו בשווה פרוטה. \u0003ו\u0004כל דבר \u0003שאין\u0004 השימוש \u0003בו\u0004 נחשב \u0003פגם\u0004 — \u0003כיון שנהנה\u0004 ממנו הנאה ששוויה פרוטה — \u0003מעל.\u0004 ומפרטים: \u0003כיצד?\u0004 — האשה ש\u0003נתנה קטלא\u0004 (שרשרת) זהב של הקדש \u0003בצוארה,\u0004 או שענדה \u0003טבעת\u0004 זהב של הקדש \u0003בידה,\u0004 או ש\u0003שתה\u0004 (שתתה) \u0003בכוס של זהב\u0004 של ההקדש. כל אלה, כיון שאין דרכם להיפגם, \u0003כיון שנהנה\u0004 מהם בשווה פרוטה — \u0003מעל.\u0004 אבל האיש ש\u0003לבש בחלוק\u0004 של הקדש, או ש\u0003כסה\u0004 עצמו \u0003בטלית\u0004 של הקדש, או ש\u0003ביקע\u0004 עצים \u0003בקרדום\u0004 של הקדש — כיון שדרך אלה להיפגם — \u0003לא מעל\u0004 בהם אף שנהנה מהם בשווה פרוטה \u0003עד שיפגום\u0004 בהם שווה פרוטה. \u0003הנהנה מן החטאת\u0004 שהיא בעלת מום, וכגון שתלש מצמרה, \u0003כשהיא חיה,\u0004 ובכך פגם בה, שהרי היא עומדת לפדיון ודמי פדיונה בשל כך יהיו נמוכים יותר — אף שנהנה שווה פרוטה, \u0003לא מעל, עד שיפגום\u0004 בה במעשהו זה בשווה פרוטה. ואם נהנה ממנה \u0003כשהיא מתה,\u0004 שמעתה אינה מן הדברים שיש בהם פגם, לפי שאינה עומדת לפדיון (שהרי אין פודים את הקדשים המתים) — \u0003כיון שנהנה\u0004 בה שווה פרוטה, הרי זה \u0003מעל.\u0004 בהסבר שיטת ר' עקיבא שבמשנה \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003מודה ר' עקיבא ל\u0004דעת \u0003חכמים\u0004 שבמשנתנו כי \u0003בדבר שיש בו פגם,\u0004 שיכול להיפגם בשימושו, אין מועלים בו עד שיפגום בו בשווה פרוטה. ושואלים: אם כן, \u0003במאי קא מיפלגי\u0004 \u0005[במה הם חלוקים],\u0006 שהרי זוהי שיטת חכמים?! \u0003אמר רבא:\u0004 שלשה סוגי מלבושים הם שלובש אדם, העליון (כגון מעיל), האמצעי, והתחתון (שעל הגוף ממש). הלבוש העליון נפגם מיד כשלובשים אותו כיון שמתחכך בקירות, וכן דוהה בחום השמש. וכן הלבוש התחתון, גם הוא נפגם מיד כשלובשים אותו, שמתחכך בגוף, וכן מזיעת הגוף ובשני אלה הכל מודים שלא מעל עד שיפגום בשווה פרוטה. ולא נחלקו אלא \u0003בלבוש מציעאה\u0004 \u0005[אמצעי]\u0006 שבין התחתון לעליון, שאינו נפגם מיד עם השימוש בו, ואולם גם הוא בסופו של דבר עתיד להפגם. \u0003ו\u0004כן ב\u0003מלמלא,\u0004 בגד העשוי מאריג דק ויקר ביותר, ששומרים אותו מאד שלא יפגם, שר' עקיבא סבור שאין אלה מכלל הדברים שיש בהם פגם, שהרי אין הפגם בא אלא לאחר זמן רב, ולכך מעל בהנאתו אף שלא פגם. ואילו חכמים סבורים שאף באלה כיון שלבסוף יבוא בהם הפגם, לכן אינו מועל אלא אם פגם בהם. ועוד בדיני המעילה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר בתורה בתחילת פרשת המעילה \u0003\"נפש\u0004 כי תמעול מעל וחטאה בשגגה מקדשי ה'...\" (ויקרא ה, טו). והרי לשון כוללת זו \"נפש\", מורה שדין זה נוהג בכל מי שהוא מוגדר כ\"נפש\", \u0003אחד היחיד\u0004 (אדם מישראל), \u0003ואחד הנשיא,\u0004 \u0003ואחד המשיח\u0004 (הכהן הגדול שנמשח בשמן המשחה לכהונתו). שאף שבדברים אחרים יש להם קרבנות חלוקים, מכל מקום שווים הם לדין המעילה.","בהמשך דברי הברייתא מבררים מה משמעות לשון \"מעילה\": עוד נאמר במקרא זה \u0003\"כי תמעל מעל\",\u0004 ו\u0003אין\u0004 משמעה של הלשון \u0003\"מעל\" אלא שנוי\u0004 מן הדרך הראויה, \u0003ו\u0004לראיה שכך הוא — ש\u0003כן הוא אומר\u0004 בפרשת האשה הסוטה \u0003\"איש איש כי תשטה אשתו ומעלה בו מעל\"\u0004 (במדבר ה, יב), \u0003ו\u0004כן \u0003אומר\u0004 הכתוב בעבודה זרה \u0003\"וימעלו באלהי\u0004"],["\u0003אבתיהם ויזנו אחרי (הבעלים)\u0004 אלהי עמי הארץ אשר השמיד אלהים מפניהם\" (דברי הימים א ה, כה). שאף בעבודה זרה, משמשת לשון זו של \"מעילה\" במשמעות של שינוי (יציאה מעבודת הקדוש ברוך הוא לעבודת האלילים). ואף המועל בהקדש משנה דברים מן המטרה שנועדו לה.","וממשיכה הברייתא: לכאורה \u0003יכול\u0004 אני ללמוד מתוך השוואת דין המעילה לעבודה זרה שנוהג דין מעילה בזמן ש\u0003פגם\u0004 בשווי ההקדש \u0003ו\u0004אף ש\u0003לא נהנה\u0004 בכך המועל, וכגון שקרע בגד של הקדש, שפגם בשוויו ולא נהנה, וכדרך עבודה זרה, שאף בה יש כעין הטלת פגם בעבודת ה', אף שאין כל הנאה מעצם העבודה לעובדיה. \u0003או\u0004 יכול אני ללמוד מתוך השוואה לסוטה שנוהג דין המעילה אף ש\u0003נהנה\u0004 מן ההקדש \u0003ולא פגם\u0004 בו, וכדרך הסוטה, שיש בה הנאת הבעילה, ואינה נפגמת בכך.","וכן יש לדון האם נוהג דין המעילה אף בזה שהשתמש \u0003ב\u0004דבר הקדש ה\u0003מחובר לקרקע.\u0004 וכן האם נוהג דין המעילה \u0003בשליח שעשה שליחותו\u0004 של אדם אחר ששלחו לעשות כן, ויתחייב במעילה המשלח ולא השליח?","\u0003תלמוד לומר\u0004 בדין המעילה צורת הלשון \u0003\"וחטאה\"\u0004 (\"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה'...\", ויקרא ה, טו) ללמדנו על כל אלה. ש\u0003נאמר\u0004 לשון \u0003\"חטא\" ב\u0004דין ה\u0003תרומה\u0004 (\"ולא תשאו עליו חטא בהרימכם את חלבו ממנו...\", במדבר יח, לב), \u0003ונאמר\u0004 לשון \u0003\"חטא\"\u0004 (\"חטאת\") \u0003במעילה,\u0004 והרי זה בא ללמדנו גזירה שווה בין תרומה לבין מעילה.","\u0003מה \"חטא\" האמור בתרומה\u0004 כוונתו ל\u0003פוגם ונהנה,\u0004 שהאוכל תרומה פוגם ונהנה; \u0003ו\u0004כשם שבתרומה \u0003מי שפגם\u0004 בה הוא זה ש\u0003נהנה\u0004 ממנה; \u0003ו\u0004כשם שבתרומה אין מתחייבים אלא כאשר \u0003ב\u0004אותו ה\u0003דבר ש\u0004בו הוא \u0003פוגם, בו\u0004 הוא \u0003נהנה; ו\u0004כן כשם שאין האוכל תרומה מתחייב אלא באופן ש\u0003פגימתו והנאתו\u0004 באים \u0003כאחד\u0004 (ביחד), שפוגם ונהנה באותו זמן; וכן כשם שאין דין תרומה נוהג אלא דווקא \u0003בתלוש מן הקרקע,\u0004 שאין שם תרומה חל על התבואה בהיותה מחוברת לקרקע. \u0003ו\u0004כן נוהג דין תרומה אף \u0003בשליח\u0004 בעל הפירות \u0003שעשה שליחותו\u0004 של בעל הבית ותרם עבורו —","\u0003אף \"חטא\" האמור במעילה\u0004 הכוונה דווקא שהמשתמש בהקדש \u0003פוגם ונהנה\u0004 מההקדש; \u0003ומי שפגם\u0004 בהקדש הוא ש\u0003נהנה\u0004 ממנו; \u0003ובדבר שפוגם בו נהנה; ופגימתו והנאתו\u0004 באים \u0003כאחד; ובתלוש מן הקרקע; ובשליח שעשה שליחותו.\u0004","וממשיכה הברייתא: \u0003אין לי\u0004 ללמוד מתוך גזירה שווה זו \u0003אלא\u0004 לענין ה\u0003אוכל\u0004 מן ההקדש, וכדין התרומה שאין חיובה אלא באכילה. \u0003ו\u0004אולם ה\u0003נהנה\u0004 מן ההקדש שלא בדרך אכילה, \u0003בדבר שאין בו פגם, מנין\u0004 שאף הוא בכלל מעילה?","וכן אם לקח דבר מאכל מההקדש ואכלו ממנו הוא וחבירו, ונמצא שגם \u0003אכילתו ו\u0004גם אכילת חברו יחד בפרוטה. מנין שחייב במעילה על אכילה זו. וכן אם נהנו הוא וחבירו מהקדש שווה פרוטה, והיתה \u0003הנייתו\u0004 (הנאתו שלו) \u0003והניית חברו\u0004 כל אחד בפחות משווה פרוטה. או שנהנה הוא וחבירו אכל, והיתה \u0003הנאתו ואכילת חברו\u0004 כל אחד בפחות משווה פרוטה. או להיפך, שאכל הוא וחבירו נהנה, והיתה \u0003אכילתו והניית חברו\u0004 כל אחד בפחות משווה פרוטה. וכן \u0003שמצטרפין\u0004 ההשתמשות בהקדש \u0003זה עם זה,\u0004 ו\u0003אפילו לזמן מרובה,\u0004 כגון שאכל חצי שיעור בזמן אחד וחצי שיעור זמן רב לאחר מכן בהעלם אחד, בכל אלה האופנים \u0003מנין\u0004 לנו שהוא בכלל דין המעילה?","\u0003תלמוד לומר\u0004 בפרשת המעילה: \"נפש כי \u0003תמעל מעל\"\u0004 — באה לשון ריבוי זו ללמדנו כי נוהג דין המעילה \u0003מכל מקום\u0004 (בכל האופנים).","ובענין זה של צירוף חלקי שיעור מעילה שנעשו בזמנים שונים דנה עוד הברייתא: \u0003אי\u0004 \u0005[אם]\u0006 עיקרי דין המעילה נלמדים מגזירה שווה לתרומה, מעתה יש לומר כך, \u0003מה \"חטא\" האמור בתרומה\u0004 — \u0003לא צירף שתי אכילות כאחד,\u0004 שאם אכל זר תרומה בפחות מכדי שיעור ביום אחד, ואכילה נוספת בפחות מכדי שיעור ביום המחרת אין שתי האכילות מצטרפות לחייבו. אם כן \u0003אף \"חטא\" האמור במעילה\u0004 בא ללמד כי אף במעילה \u0003לא צירף שתי אכילות כאחד.\u0004 ומעתה יש לשאול \u0003מנין\u0004 לנו שאם \u0003אכל\u0004 מן ההקדש בשיעור שאין בו חיוב מעילה \u0003היום\u0004 וחזר שוב \u0003ואכל\u0004 ממנו \u0003למחר\u0004 שיעור שאין בו חיוב, \u0003ואפילו\u0004 חזר ואכל \u0003לזמן מרובה\u0004 שהם מצטרפים לחיוב מעילה? \u0003תלמוד לומר:\u0004 \"נפש כי \u0003תמעל מעל\"\u0004 — לחייבו \u0003מכל מקום,\u0004 בכל האופנים, ואף באופן זה.","וכיוצא בדבר דנה עוד הברייתא: אחר שדין המעילה נלמד מתרומה, יש לברר \u0003אי\u0004 \u0005[אם]\u0006 \u0003מה \"חטא\" האמור בתרומה\u0004 — אינו נוהג אלא כאשר הן \u0003פגימתו\u0004 בתרומה \u0003ו\u0004הן \u0003הנאתו\u0004 ממנה באים \u0003כאחד,\u0004 והוא הדין במעילה, ואולם \u0003מנין\u0004 לנו שיש דין מעילה גם \u0003ל\u0004ענין \u0003אכילתו ואכילת חברו\u0004 שבכל אחת מהן אין שיעור מעילה, ולא היו בזמן אחד? \u0003ואפילו\u0004 היו שתי אכילות אלה מרוחקות בזמן זו מזו \u0003מכאן ועד שלש שנים, מנין\u0004 לנו שהם מצטרפות, וחייב עליהן? \u0003תלמוד לומר:\u0004 \"נפש כי \u0003תמעל מעל\"\u0004 — לחייבו \u0003מכל מקום,\u0004 בכל האופנים, ואף באלה.","ועוד דנה הברייתא. \u0003אי\u0004 \u0005[אם]\u0006 אכן נלמדים דיני המעילה מגזירה שווה לתרומה, יש מקום לומר: \u0003מה \"חטא\" האמור בתרומה\u0004"],["אין הזר (שאינו כהן) האוכל את התרומה חייב \u0003עד שיצא מן הקדש לחול,\u0004 שהרי באכילתו הוא מוציאה לחולין, הוא הדין אף במעילה הנלמדת מן התרומה בגזירה שווה זו.","ואולם מניין לנו שתהא מעילה נוהגת אף אם הוציא חפץ הקדש \u0003מן הקדש לקדש?\u0004 \u0003כגון ש\u0004\u0003לקח\u0004 (קנה) מכספי הקדש \u0003קיני\u0004 (זוג תורים או בני יונה) לקרבן טהרת ה\u0003זבים, וקיני זבות, וקיני יולדות.\u0004 שבכל אלה אף שמשתמש בכסף הקדש לצורך קודש, כיון שחייב בהקרבת קרבנות, ועליו להביאם מכספו הפרטי, נמצא שכשמביאם מכספי המקדש הריהו נהנה מהם.","\u0003ו\u0004מי ש\u0003שקל שקלו\u0004 (מחצית השקל שחייב) מכספי ההקדש. \u0003ו\u0004ש\u0003הביא\u0004 את קרבנות \u0003חטאתו ואשמו\u0004 שהוא חייב בהבאתם \u0003מן\u0004 הכסף של \u0003ההקדש.\u0004 שאף שהוציאו לצורך קודש — מעל. ונחלקו חכמים ממתי חלה המעילה. לשיטה אחת \u0003כיון\u0004 (בזמן) \u0003שהוציא\u0004 את הכסף — \u0003מעל,\u0004 אלו \u0003דברי ר' שמעון.\u0004 ואילו \u0003ר' יהודה אומר:\u0004 לא מעל \u0003עד שיזרוק ה\u0004כהן את \u0003דם\u0004 הקרבנות הללו, והתכפר בהם המביא אותם. ויש לשאול: \u0003מנין\u0004 לנו שגם זו קרויה מעילה? \u0003תלמוד לומר\u0004 בדין המעילה: \"נפש כי \u0003תמעל מעל\"\u0004 (ויקרא ה, טו), ומכפל הלשון למדים שנוהגת היא \u0003מכל מקום,\u0004 בכל האופנים, ואף במוציא מקודש לקודש.","ושבים לברר את תחילת דברי הברייתא. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: מן הכתוב בפרשת המעילה \u0003\"נפש\u0004 כי תמעול מעל\" למדים כי בכלל מעילה כל שהוא בכלל \"נפש\", אחד היחיד, ואחד הנשיא, ואחד המשוח במשמע. ושואלים: ממה שרוצים להשמיענו בדרשה זו למדים אנו \u0003שיכול\u0004 היה לומר דבר אחר, ו\u0003מאי\u0004 \u0005[מה]\u0006 הוא? אם תאמר שאין הנשיא או המשוח כלולים בדין המעילה? — אי אפשר לומר זאת שהרי \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא הדבר, שכן \u0003\"נפש\" כתיב\u0004 \u0005[נאמר],\u0006 ובכלל זה הכל!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שאין אלה בכלל מעילה, שהרי \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 באיסור השימוש בשמן המשחה \u0003\"ואשר יתן ממנו על זר\u0004 ונכרת מעמיו\" (שמות ל, לג), \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 הכהן המשוח וכן המלך הנמשח בשמן המשחה, \u0003לאו\u0004 \u0005[לא]\u0006 בכלל \u0003\"זר\" הוא, דהא אימשח בגוויה\u0004 \u0005[שהרי\u0006 כבר \u0005נמשח בו],\u0006 והדבר שייך בו ואין הם עוד בכלל דין מעילה בכך. משום כך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא שבברייתא \u0005משמיע לנו]\u0006 שאף הנשיא והכהן המשוח בכלל.","\u0003ו\u0004נפנים עתה לסיכום הדרשות שנאמרו בדין המעילה. \u0003אקשה רחמנא\u0004 \u0005[והקישה אותה התורה,\u0006 את המעילה\u0005]\u0006 \u0003לסוטה,\u0004 שנאמר בה \"ומעלה בו מעל\" (במדבר ה, יב). \u0003ו\u0004כן הקישה התורה את המעילה \u0003לעבודה זרה,\u0004 שנאמר בה \"וימעלו באלקי אבותיהם\" (דברי הימים א' ה, כה), \u0003ו\u0004כן הקישה התורה את המעילה \u0003לתרומה\u0004 בגזירה שווה \"חטא\" \"חטא\", כמבואר בעמוד הקודם. ומהיקשים אלה נלמדים עיקר דיני המעילה. ומפרטים: מן ההיקש \u0003לסוטה\u0004 למדים אנו שכשם שדין הסוטה חל על הנאה \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא פגם\u0004 באשה בהנאתו זו, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003הקדש נמי\u0004 \u0005[גם כן],\u0006 אם נהנה ממנו אף שלא פגם בו, כגון האשה ש\u0003נתנה טבעת\u0004 זהב (שהיא דבר שאינו נפגם) של הקדש \u0003בידה\u0004 — \u0003מעלה.\u0004","ו\u0003כי אקשה רחמנא\u0004 \u0005[כאשר הקישה אותה,\u0006 את המעילה, \u0005התורה]\u0006 \u0003לעבודה זרה,\u0004 הרי זה מלמד שכשם שבעבודה זרה אין אדם מתחייב בה \u0003עד דאית\u0004 \u0005[שיש]\u0006 \u0003בה שינוי\u0004 (שכן עיקר העבודה זרה הריהי שינוי והוצאה מרשות הקדוש ברוך הוא לרשות אחרים), \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003הקדש נמי\u0004 \u0005[גם כן]\u0006 — אין אדם מתחייב במעילה אלא \u0003עד\u0004 שישנה בה ממלאכת קודש למלאכת חול, וכגון ש\u0003ביקע\u0004 עצי חולין \u0003בקרדום\u0004 של הקדש, ויפגם את הקרדום בכך, \u0003ו\u0004ימצא ההקדש \u0003פגום.\u0004","וכן \u0003אקשה רחמנא\u0004 \u0005[הקישה אותה,\u0006 את המעילה, \u0005התורה]\u0006 \u0003לתרומה,\u0004 ללמדנו: \u0003מה\u0004 ב\u0003תרומה\u0004 משמעות הכתוב \"ואיש \u0003כי יאכל\u0004 קדש בשגגה ויסף חמישיתו עליו...\" (ויקרא כב, יד) — \u0003פרט למזיק\u0004 את התרומה שלא בדרך אכילה (כגון ששפך יין תרומה), שאינו מוסיף חומש על הקרן, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003הקדש נמי\u0004 \u0005[גם כן]\u0006 \u0003כל\u0004 הקדש שהוא \u0003בר\u0004 \u0005[בן]\u0006 \u0003אכילה,\u0004 כלומר, ראוי לאכילה, \u0003כי\u0004 \u0005[כאשר]\u0006 אין אדם אוכלו, אלא \u0003מזיק ליה\u0004 \u0005[אותו]\u0006 — הריהו \u0003פטור\u0004 מדין מעילה.","שנינו במשנתנו כי דבר הקדש שאינו נפגם כשמשתמשים בו — כיון שנהנה ממנו בשווה פרוטה, הרי זה מעל. \u0003כיצד\u0004 היא המעילה בדבר שאין דרכו להיפגם? — כגון האשה ש\u0003נתנה קטלא\u0004 העשויה זהב של הקדש בצוארה, וכיוצא בזה. ובענין זה \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא לרב זביד\u0004 בשאלה: \u0003ו\u0004האם \u0003דהבא לאו בר איפגומי\u0004 \u0005[זהב לא בן פגימה]\u0006 \u0003הוא?\u0004 \u0003והא דהבא דכלתיה\u0004 \u0005[והרי\u0006 כלי \u0005הזהב של כלתו],\u0006 אשת בנו של העשיר הנודע \u0003נון,\u0004 שבשעה שהשיא את בנו, נתן תכשיטי זהב מרובים לכלתו, ולאחר מכן איבדו הרבה ממשקלם ומערכם, ואם חפצים העשויים זהב אינם נפגמים, אם כן להיכא אזל \u0005[לאן הלך]\u0006 משקלם? אלא ודאי שאף חפצים העשויים זהב נפגמים! \u0003אמר\u0004","\u0003ליה\u0004 \u0005[לו]\u0006 רב זביד לרב כהנא: \u0003דלמא\u0004 \u0005[שמא]\u0006 תכשיטי כלתו של נון איבדו ממשקלם וערכם משום שלא נשמרו כראוי, ובכגון זה עשוי גם הזהב להיפגם, כדרך \u0003דהבא דרמיין כלתיך\u0004 \u0005[\u0006תכשיטי \u0005הזהב שמשליכות אותם כלותיך]\u0006 \u0003הוא,\u0004 שלא היו שומרות כראוי את תכשיטיהן. \u0003ועוד\u0004 יש לומר: \u0003נהי דלא איכא\u0004 \u0005[אם אמנם שאין כאן],\u0006 משום \u0003נהנה ופגם לאלתר\u0004 (מייד), ואולם בשימוש \u0003לעולם\u0004 (כלומר, לזמן רב) \u0003מי לא איכא\u0004 \u0005[האם אין כאן,\u0006 שייכת\u0005]\u0006 \u0003פגימה?\u0004","עוד שנינו במשנתנו ש\u0003הנהנה מן החטאת\u0004 או משאר קדשי קדשים, וכגון שתלש מצמרה, אם עשה כן בחייה של הבהמה — לא מעל עד שיפגום בה בשווה פרוטה. ומקשים על כך: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בבהמה תמימה\u0004 העומדת להקרבה עוסקים אנו, הרי בהמת חטאת זו \u0003היינו\u0004 \u0005[זהו]\u0006 כמו \u0003כוס של זהב\u0004 שאין בו פגם, שכן אף לאחר שתלש את צמרה אין הדבר נחשב כפגם, ועדיין קרבה היא על המזבח, ומדוע אין מועלים בה אלא אם כן נפגמה בשווה פרוטה? \u0003אמר רב פפא: ב\u0004בהמה \u0003בעלת מום עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שאין היא עומדת להקרבה, אלא להיפדות. ומעתה, הריהי בכלל הדברים שיש בהם פגם, שכן תלישת צמרה פוגמת בערכה, וככל שערכה נמוך, אף מחיר פדיונה נמוך. ודינה איפוא שאין מועלים בה אלא אם כן אף פגמו בה."],["ה\u0003נהנה\u0004 מן ההקדש הנאה ששוויה \u0003כבחצי פרוטה ופגם\u0004 (הפחית מערכו של ההקדש) בתוך כך \u0003ב\u0004שיעור \u0003חצי פרוטה. או שנהנה\u0004 מן ההקדש \u0003בשוה פרוטה בדבר אחד\u0004 של ההקדש העשוי להיפגם (\"שיש בו פגם\"), ולא פגם בו אף שנהנה ממנו, \u0003ופגם בשוה פרוטה בדבר אחר\u0004 של ההקדש, אף שלא נהנה ממנו — \u0003לא מעל, עד שיהנה בשוה פרוטה ו\u0004גם \u0003יפגם בשוה פרוטה בדבר אחד\u0004 של הקדש.","\u0003אין\u0004 אדם \u0003מועל\u0004 בחפצי הקדש ל\u0003אחר\u0004 שהיה כבר לפניו אדם אחר שהיה \u0003מועל ב\u0004אותם \u0003מוקדשין, אלא\u0004 (מלבד) ב\u0003בהמה\u0004 שאין בה מום ועומדת להקרבה, \u0003וכלי שרת,\u0004 שבאלו \u0003בלבד\u0004 יש מעילה אחר מעילה. \u0003כיצד?\u0004 הוא אופן בו משתמשים כמה בני אדם בבהמת הקדש: \u0003רכב על גבי בהמה\u0004 העומדת להקרבה, \u0003ובא\u0004 אחר כן \u0003חברו ורכב\u0004 אף הוא, \u0003ובא חברו,\u0004 אדם נוסף, \u0003ורכב\u0004 אף הוא על בהמה זו — \u0003כולן מעלו.\u0004 ובכלי שרת — כגון ש\u0003שתה\u0004 אחד \u0003בכוס של זהב, ובא\u0004 אחריו \u0003חברו ושתה\u0004 גם כן מאותו הכוס, \u0003ובא חברו ושתה\u0004 אף הוא מאותו הכוס — \u0003כולן מעלו.\u0004 וכן אחד ש\u0003תלש\u0004 צמר \u0003מן החטאת, ובא חברו ותלש\u0004 גם הוא מאותה בהמה, \u0003ובא חברו ותלש\u0004 אף הוא — \u0003כולן מעלו. רבי אומר: כל דבר שאין לו פדיון,\u0004 שאי אפשר לפדותו — \u0003יש בו\u0004 מצב שיהיה אדם זה \u0003מועל אחר\u0004 אדם אחר ה\u0003מועל.\u0004","שנינו במשנתנו שאין מעילה אחר מעילה אלא בבהמה ובכלי שרת, ומבררים: כשיטת \u0003מני מתניתין\u0004 \u0005[מי,\u0006 איזה תנא, \u0005היא משנתנו]?\u0006 — כשיטת \u0003ר' נחמיה היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין מועל אחר מועל אלא בבהמה בלבד,\u0004 שכן בהמה העומדת להקרבה על המזבח אין לה פדיון, ואם מעל בה — לא התחללה בכך. ואולם כלי שרת, שיש להם פדיון — אין בהם מעילה אחר מעילה, שכיון שמעל בהם, הוציאם לחולין, ושוב לא שייך למעול בהם. ואילו \u0003ר' נחמיה אומר:\u0004 יש מועל אחר מועל הן ב\u0003בהמה והן\u0004 ב\u0003כלי שרת.\u0004","ושואלים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה הטעם של התנא הראשון]\u0006 החלוק על ר' נחמיה וסבור שאין מועל אחר מועל בכלי שרת? ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כי כיון ש\u0003בעניינא\u0004 \u0005[בענין]\u0006 המעילה, ב\u0003בהמה כתיב\u0004 \u0005[נאמר]\u0006 הדבר, דכתיב \u0005[ש\u0006כן \u0005נאמר]\u0006 \"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה' והביא את אשמו לה' איל תמים מן הצאן... ואת אשר חטא מן הקודש ישלם ואת חמישתו יוסף עליו... והכהן יכפר עליו \u0003באיל האשם\u0004 ונסלח לו\" (ויקרא ה, טו—טז), וודאי לשון \"איל האשם\" בא ללמד שדווקא בבהמה נוהג דין מעילה אחר מעילה, ולא בכלי שרת.","\u0003ו\u0004אילו \u0003ר' נחמיה\u0004 הסבור שאף בכלי שרת יש מעילה אחר מעילה, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך\u0004 שהדבר נלמד מ\u0003קל וחומר: אם\u0004 את ה\u0003אחרים\u0004 (הנכנסים לכלי שרת) \u0003מביא\u0004 אותם כלי השרת \u0003לקדושתן\u0004 ולדין מעילה, \u0003הוא עצמו\u0004 — \u0003לא כל שכן\u0004 שאינו יוצא לחולין על ידי מעילה, ויש בו מעילה אחר מעילה!","שנינו במשנתנו, \u0003רבי אומר: כל דבר שאין לו פדיון, יש\u0004 בו מועל אחר מועל. ושואלים: והרי \u0003היינו\u0004 \u0005[זהו]\u0006 כשיטת ה\u0003תנא קמא\u0004 \u0005[הראשון\u0006 שבמשנתנו\u0005],\u0006 ומה הוסיף רבי? \u0003אמר רבא: איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל להלכה בענין נדבת \u0003עצים.\u0004 תנא קמא סבור שאין דינם של עצים כקדשי מזבח, אלא כקדשי בדק הבית, שיש בהם פגם, ומשום כך — אין בהם מעילה אחר מעילה. ואילו רבי סבור שדין העצים כדין קדשי מזבח, שאין בהם פגם, ועל כן יש בהם מעילה אחר מעילה.","\u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0003שנו חכמים\u0004 בברייתא\u0005]:\u0006 \u0003האומר\u0004 בלשון נדר \u0003\"הרי עלי\u0004 להביא \u0003עצים\u0004 למקדש\", ולא פירש כמה — \u0003לא יפחות משני גזירין\u0004 (חתיכות עץ, כחתיכות הערוכות על המזבח). \u0003רבי אומר: עצים\u0004 — \u0003קרבן הן\u0004 נחשבים, שכן עולים הם על המזבח, \u0003וטעונין מלח, וטעונין תנופה\u0004 כמו קרבן מנחה.","\u0003אמר רבא: לדברי רבי\u0004 שעצים נחשבים לקרבן, אם כן הנודר \u0003עצים\u0004 — אותם עצים \u0003טעונין\u0004 בהבאת \u0003עצים\u0004 אחרים על מנת לשרוף אותם כקרבן הטעון עצים, ואף זה בכלל חיוב נדרו. והוסיף \u0003ואמר רב פפא: לדברי רבי,\u0004 אם נדר \u0003עצים\u0004 הריהם \u0003צריכין קמיצה\u0004 (שיקח מקצת מהעצים בקומצו, ויקטירם תחילה), כדרך קרבן המנחה.","\u0003רב פפא אמר\u0004 הסבר אחר להבדל בין שיטת התנא קמא במשנתנו ושיטת רבי: \u0003קדשי מזבח\u0004 שהיו בתחילתם \u0003תמימין\u0004 ועומדים להקרבה על המזבח, \u0003ונעשו בעלי מומין\u0004 ונפסלו להקרבה, \u0003ועבר\u0004 אדם \u0003ושחטן\u0004 לפני שנפדו, באופן זה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בין רבי ותנא קמא.","\u0003והתניא\u0004 \u0005[ו\u0006אכן כך \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003קדשי מזבח תמימין, ונעשו בעלי מומין, ועבר ושחטן, רבי אומר:\u0004 אין קדשים אלה שנשחטו ראויים עוד להיפדות, שהרי בפדיון קדשים נאמר \"...והעמיד את הבהמה לפני הכהן. והעריך הכהן אותה...\" (ויקרא כז, יא—יב), ואלה שמתו אין אפשרות להעמידן לצורך הערכתן, ומשום כך \u0003יקברו,\u0004 כפסולי המוקדשים, ללא פדיון.","\u0003וחכמים אומרים: יפדו, ונמצא כי לשיטת רבי כיון שאין הם נפדים — קדושתם קדושת הגוף, ויש בהם מעילה אחר מעילה. ואילו תנא קמא סבור כי כיון שנפדים הם — קדושתם קדושת דמים, ואין בהם מעילה אחר מעילה.\u0004","\u0003נטל\u0004 לשימושו \u0003אבן או קורה של\u0004 ה\u0003הקדש\u0004 — \u0003הרי זה לא מעל\u0004 בכך."],["ואם \u0003נתנה\u0004 את האבן או את הקורה הזו \u0003לחברו\u0004 — \u0003הוא מעל,\u0004 לפי שהוציאן בכך מרשות ההקדש לרשות חולין. \u0003ו\u0004אילו \u0003חברו לא מעל\u0004 שכן בשעה שניתנה לו — כבר יצאה מרשות ההקדש. \u0003בנאה\u0004 את האבן או את הקורה \u0003בתוך ביתו\u0004 — \u0003הרי זה לא מעל,\u0004 כיון שבבנייה כשלעצמה, עדיין לא נהנה ממנה, \u0003עד שידור תחתיה\u0004 ויהנה ממגורים אלה \u0003בשוה פרוטה.\u0004","\u0003נטל\u0004 לעצמו \u0003פרוטה של הקדש\u0004 — \u0003הרי זה לא מעל\u0004 בכך. ואם \u0003נתנה לחברו\u0004 — \u0003הוא\u0004 עצמו \u0003מעל,\u0004 שהוציאה בכך מרשות הקדש לרשות חולין, \u0003ו\u0004אילו \u0003חברו\u0004 המקבל \u0003לא מעל\u0004 בכך. \u0003נתנה\u0004 את הפרוטה הזו \u0003לבלן\u0004 (העובד בבית המרחץ) כתשלום עבור רחצה, \u0003אף על פי ש\u0004עדיין \u0003לא רחץ\u0004 — \u0003מעל\u0004 בכך, וטעם הדבר: \u0003ש\u0004כן משעה ששילם, \u0003הוא\u0004 הבלן \u0003אומר לו: הרי המרחץ פתוח לפניך, הכנס ורחוץ,\u0004 שיש לו רשות לרחוץ מיד בבית המרחץ, ורשות זו עצמה הנאה היא לו.","\u0003אכילתו\u0004 שאכל מן ההקדש בשווי כחצי פרוטה \u0003ואכילת\u0004 הקדש שהאכיל הוא את \u0003חברו\u0004 כחצי פרוטה, וכן \u0003הנייתו\u0004 (הנאה שנהנה הוא) מן ההקדש בשווי כחצי פרוטה \u0003והניית חברו\u0004 (שהוא מהנה את חבירו) בשווי כחצי פרוטה, וכן \u0003אכילתו והניית חברו,\u0004 וכן \u0003הנייתו\u0004 שלו \u0003ואכילת חברו\u0004 — כל אלה \u0003מצטרפין זה עם זה\u0004 לשיעור מעילה, שהוא בפרוטה, וחייב בדיני המעילה. \u0003ואפילו\u0004 חלף \u0003זמן מרובה\u0004 בין האכילות או ההנאות הללו. שנינו במשנתנו כי זה שנטל אבן או קורה משל הקדש לעצמו — לא מעל בכך, ואולם אם נתנה לחברו — מעל. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003הוא\u0004 שנטל לעצמו, שלא מעל, \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה]\u0006 הוא שנתן ל\u0003חבירו,\u0004 שמעל?! \u0003אמר שמואל:\u0004 המשנה מדברת \u0003בגזבר\u0004 ההקדש, שהאבנים והקורות הללו \u0003מסורות לו עסקינן\u0004 \u0005[עוסקים אנו].\u0006 שכיון שהמעות שמורות בידו הרי עצם ההחזקה בהן אינה מעילה, אבל כשהוא נותנן לאחרים — הרי זו מעילה.","","עוד שנינו במשנתנו שאם לקח אבן או קורה של הקדש, ו\u0003בנאה בתוך ביתו\u0004 — \u0003אינו חייב\u0004 משום מעילה, עד שידור תחתיה. ושואלים: \u0003למה לי\u0004 להמתין בחיובו \u0003עד שידור תחתיה?\u0004 והרי \u0003כיון דשניה\u0004 \u0005[ששינה אותה]\u0006 שסיתת אותה לצורך קביעתה בתוך הבנין — הוציאה בכך מרשות הקדש ו\u0003מעל! אמר רב:\u0004 אין המדובר שבנאה ממש בתוך ביתו, אלא ב\u0003כגון שהניחה על פי ארובה\u0004 (חור, כעין חלון בתקרה). וכיון שאין שינוי בעצם ההנחה אינו מתחייב במעילה עד שידור תחתיה. \u0003ו\u0004מעירים: אחר שהסברנו כך את דברי משנתנו, הרי מובן כי \u0003כיון\u0004 (מתוך) \u0003דבני לה\u0004 \u0005[שבנה אותה],\u0006 את האבן בבנין \u0003מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003מעל,\u0004 אף שהאבן עתה חלק מבית המחובר לקרקע, וכלל הוא שאין מעילה בדבר המחובר לקרקע. ואם כן האם \u0003לימא\u0004 \u0005[\u0006יש \u0005לומר]\u0006 שדבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב, דאמר\u0004 \u0005[שאמר]\u0006 \u0003רב: המשתחוה לבית\u0004 לשם עבודה זרה — \u0003אסרו\u0004 בכך באיסור הנאה, שהבית אינו נחשב כמחובר לקרקע, כיון שנבנה מאבנים וקורות שהיו בתחילתן תלושות ורק לאחר מכן חוברו, וכלל הוא: תלוש ולבסוף חברו — דינו כתלוש, והוא הדין אם כן גם באבן הקדש שהניחה על פי הארובה, שמכיון שהיתה בתחילה תלושה, יש בה דין מעילה?!","","\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא\u0004 בדחייה: אין להביא מכאן ראיה לשיטת רב, שכן אפשר לומר שסבורה משנתנו כי דינו של התלוש שחובר לקרקע הריהו כדין המחובר מעיקרו, ולכן אין המשתחוה לבית לעבודה זרה אוסרו. ואף על פי כן באבן או בקורת הקדש שנבנו בבית יש דין מעילה, כי בדין המעילה בדברי הקדש כל \u0003הנאה הנראת לעינים\u0004 (הניכרת שאדם נהנה בדבר, וכגון זה היושב בבית שנבנו בו האבן או הקורה) \u0003אסרה תורה\u0004 בדין המעילה.","ומציעים עוד: \u0003לימא\u0004 \u0005[\u0006האם יש מקום \u0005לומר]\u0006 כי \u0003מסייע ליה\u0004 \u0005[לו,\u0006 לרב\u0005]\u0006 בשיטתו (כי תלוש ולבסוף מחובר נחשב כתלוש) מה ששנינו בברייתא: אדם \u0003הדר בבית של הקדש, כיון שנהנה ממנה\u0004 — \u0003מעל,\u0004 ונראים הדברים שמדובר בבית בנוי שעמד אדם והקדישו. הרי שכיון שהיה בתחילה תלוש (אבניו וקורותיו), אף שלבסוף עמד וחיברו, הריהו נחשב כתלוש ולכן יש בו מעילה. \u0003אמר ריש לקיש\u0004 בדחייה: אין להביא ראיה משם, שכן \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003ב\u0004מקרה \u0003שהקדישו\u0004 את אבני וקורות הבית בעודם תלושים, \u0003ולבסוף בנאו\u0004 בהם.","ושואלים על העמדה זו של ריש לקיש את דברי הברייתא: \u0003אבל\u0004 לפי הסבר זה, במקרה ש\u0003בנאו\u0004 בתחילה את הבית \u0003ולבסוף הקדישו מאי\u0004 \u0005[מה]\u0006 יהא הדין — ש\u0003לא מעל?\u0004 אם כן, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מה ענין זה\u0005]\u0006 ש\u0003רהיט ותני\u0004 \u0005[מיהר\u0006 התנא בברייתא \u0003ושנה]\u0004 את הדין הבא המדבר באופן אחר לגמרי, באדם \u0003הדר בבית של מערה,\u0004 כלומר, בסוג בית שלא היה מעולם (הוא וחומריו) תלוש — \u0003לא מעל\u0004 בכך, שכן אין מעילה במחובר. \u0003לימא\u0004 \u0005[שיאמר]\u0006 התנא דין במקרה של אדם \u0003הדר בבית של אבנים, שבנאו\u0004 בתחילה בחול, \u0003ולבסוף הקדישו\u0004 — הרי זה \u0003לא מעל!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לשאלה זו: אכן יכול היה התנא לומר כן, ואולם העדיף להשמיע דין זה דווקא במערה, כי \u0003הא\u0004 \u0005[זה,\u0006 מגורים במערה\u0005]\u0006 \u0003פסיקא ליה\u0004 \u0005[פסוק,\u0006 מוחלט וברור, \u0005לו]\u0006 שבכל מצבי המגורים בבית מערה קיים דין אחד — שאינו מועל בכך. ואילו \u0003הא\u0004 \u0005[זה,\u0006 בית אבנים\u0005]\u0006 \u0003לא פסיקא ליה\u0004 \u0005[אינו פסוק לו],\u0006 שהרי יש בו מעילה רק באופן מסויים, שבנאו בחול ולאחר מכן הקדישו.","","\u0003השליח שעשה\u0004 את \u0003שליחותו\u0004 של בעל הבית, כפי שנאמרה לו, ובשליחות זו השתמש לצורך חולין בכספי הקדש שניתנו לו על ידי בעל הבית בשוגג — \u0003בעל הבית\u0004 ששלח אותו הוא ש\u0003מעל,\u0004 ולא השליח (שלא כבשאר דיני התורה שהכלל הנוהג בהם הוא ש\"אין שליח לדבר עבירה\", והשליח הוא החייב על מעשה העבירה שנעשה על ידו). ואולם אם \u0003לא עשה\u0004 השליח את \u0003שליחותו\u0004 כפי שהצטווה על ידי בעל הבית ששלחו — \u0003השליח\u0004 הוא ש\u0003מעל.\u0004","ומפרטים: \u0003כיצד\u0004 הוא אופן זה שהשליח לא עשה את שליחותו של בעל הבית? כגון ש\u0003אמר לו\u0004 בעל הבית לשליח \u0003\"תן בשר לאורחים!\", ו\u0004אילו הוא עמד ו\u0003נתן להם כבד,\u0004 ולא בשר. או במקרה הפוך שאמר לו בעל הבית שיתן לאורחים כבד, והוא עמד \u0003ונתן להם בשר\u0004 ולא כבד, והיו הבשר והכבד של הקדש — באופנים אלה ובדומה להם, \u0003השליח\u0004 הוא ש\u0003מעל\u0004 ולא בעל הבית, כיון ששינה ולא עשה את שליחותו. אבל אם היה לבעל הבית בשר של הקדש ו\u0003אמר לו\u0004 בעל הבית: \u0003\"תן להם\u0004 לאורחים, בשר באופן זה שאורח זה יקבל \u0003חתיכה\u0004 אחת של בשר, ואורח זה יקבל \u0003חתיכה\u0004 אחת של בשר\". \u0003ו\u0004אילו \u0003הוא\u0004 המלצר \u0003אומר\u0004 לאורחים על דעת עצמו: \u0003\"טלו\u0004 לכם, כל אחד מאתכם, \u0003שתים\u0004 חתיכות!\", \u0003והם\u0004 האורחים \u0003נטלו\u0004 מדעת עצמם, כל אחד מהם, \u0003שלש\u0004 חתיכות, והיו אלה חתיכות בשר של הקדש — \u0003כולם מעלו.\u0004 בעל הבית מעל — על אכילת החתיכה הראשונה, שבזאת קיים השליח את דברי בעל הבית. המלצר מעל — על אכילת החתיכה השניה, שבה הוסיף על השליחות. והאורחים מעלו — על אכילת החתיכה השלישית, שבה הוסיפו הם על דברי השליח."],["מתוך דברי המשנה שכאשר שינה השליח מדברי בעל הבית ונתן לאורחים כבד במקום בשר, או להיפך — עולה כי בשר וכבד הם שני דברים שונים והחילוף ביניהם הוא מן הדברים שעליהם כרגיל שליח נמלך עם משלחו, כגון אם שלחו לקנות לו בשר ולא מצא השליח אלא כבד — הריהו נמלך עם משלחו אם יקנה את הכבד. ומבררים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כי \u0003כל מילתא דמימלך עלה\u0004 \u0005[כל דבר שנמלך עליו]\u0006 \u0003שליח\u0004 עם משלחו סימן הוא כי \u0003תרתי מילי הויין\u0004 \u0005[שני דברים\u0006 שונים \u0005הם]?\u0006","\u0003אמר רב חסדא:\u0004 דבר זה הוא ש\u0003לא כ\u0004שיטת \u0003ר' עקיבא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנודר\u0004 (אוסר עצמו בנדר) \u0003מן\u0004 אכילת \u0003הירק,\u0004 ולא פירט מאלו ירקות — חכמים אומרים: \u0003מותר בדילועין. ו\u0004אילו \u0003ר' עקיבא אוסר,\u0004 שלדעתו כיון שהשליח נמלך בדעת משלחו בענין הדלועים, בכך הוא מראה כי הם מין אחד, שאילולי כן לא היה נמלך בו כלל — הרי שלדעת ר' עקיבא דבר שנמלך עליו השליח הינו בכלל הדבר שנשלח אליו, ואין זה כשיטת משנתנו.","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהמשנה כשיטת \u0003ר' עקיבא,\u0004 שבבשר וכבד כיון שנמלך במשלחו אין זה נחשב כקיום השליחות והשליח הוא שמועל. ואולם אין זה משום שכאשר נמלך השליח הרי הם נחשבים שני דברים שונים, אלא אף אם הם כדבר אחד מודה ר' עקיבא שהשליח הוא שמועל, שכן \u0003מי\u0004 \u0005[האם]\u0006 ר' עקיבא עצמו \u0003לא\u0004 מודה שעל כל פנים, \u0003בעי לאימלוכי\u0004 \u0005[צריך\u0006 השליח \u0005להתייעץ]\u0006 עם משלחו? וכיון שלא נמלך השליח, ועשה מדעת עצמו — אין זה נקרא עושה שליחותו של משלחו. ומסופר ביחס לכך, \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמרו רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רבא\u0004 את דבריו אלה של אביי, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003נחמני\u0004 (אביי)!","מתוך שהוזכרה מחלוקת ר' עקיבא וחכמים, דנים עוד בדבר. \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא דפליג עליה\u0004 \u0005[שחולק עליו]\u0006 על \u0003ר' עקיבא?\u0004 ומשיבים: \u0003רבן שמעון בן גמליאל היא, דתניא\u0004 \u0005[ש\u0006כן שנויה ברייתא\u0005]:\u0006 \u0003הנודר מן הבשר\u0004 — \u0003אסור בכל מיני בשר\u0004 הבהמה. \u0003ואסור\u0004 אף באותם חלקי בשר שאין אנשים אוכלים אותם כרגיל: \u0003בראש, וברגלים,\u0004 ו\u0003בקנה, ובכבד, ובלב. ואסור\u0004 כמו כן אף \u0003בבשר עופות. ו\u0004אולם הריהו \u0003מתיר בבשר דגים וחגבים,\u0004 שאין אלה בכלל \"בשר\". ואילו \u0003רבן שמעון בן גמליאל מתיר בראש וברגלים, בקנה ובכבד ובעופות, ו\u0004אין צורך לומר שלדבריו הריהו מותר \u0003ב\u0004בשר \u0003דגים ובחגבים.\u0004","\u0003וכן היה רבן שמעון בן גמליאל אומר: קרביים\u0004 (החלקים הפנימיים של הבהמה) \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בשר הן, ואוכליהן לאו בר איניש\u0004 \u0005[אינו בן אדם],\u0006 שאין הוא נוהג כדרך בני אדם. הרי שרבן שמעון בן גמליאל הוא החולק על ר' עקיבא, וסבור הוא שאף שכבד הוא מן הדברים ששליח נמלך עליהם, מכל מקום אין הוא בכלל בשר לענין הנדרים.","ושואלים: \u0003ול\u0004שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שבברייתא זו, האוסר בשר עוף ומתיר דגים, \u0003מאי שנא\u0004 \u0005[מה\u0006 המיוחד, \u0005השונה]\u0006 \u0003בבשר עופות\u0004 שהוא מחשיב אותו בגדר בשר? — \u0003משום\u0004 ש\u0003רגיל\u0004 (מצוי הדבר) כי \u0003איניש\u0004 \u0005[אדם]\u0006 הנשלח לקנות בשר בהמה \u0003דאמר\u0004 \u0005[ש\u0006קונה בשר עוף ו\u0005אומר]\u0006 הוא למשלחו: \u0003לא אשכחי בשרא דחיותא, ואתאי בשרא דציפרא\u0004 \u0005[לא מצאתי בשר בהמות, והבאתי בשר ציפורים,\u0006 עופות\u0005].\u0006 ומעתה יש לשאול, \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא הטעם לאיסור בשר עופות לשיטתו של התנא קמא, \u0003הכי נמי עביד איניש למימרא\u0004 \u0005[כך גם כן\u0006 לענין דגים \u0005עשוי אדם\u0006 זה \u0005לומר]:\u0006 \u0003לא אשכחי בשרא דחיותא, ואתאי\u0004 \u0005[לא מצאתי בשר בהמות, והבאתי]\u0006 בשר \u0003דגים!\u0004","\u0003אמר רב פפא:\u0004 בברייתא זו \u0003ביום הקזה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דלא אכיל איניש\u0004 \u0005[שאין אוכל אדם]\u0006 \u0003דגים\u0004 ביום זה, כיון שמזיק הדבר. ומשום כך, ביום זה אין נמלך השליח על דגים.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003ציפרא נמי ניכול\u0004 \u0005[\u0006בשר \u0005עוף גם כן שיאכל]\u0006 הנודר, שהרי אין נכון לאכול בשר עוף ביום הקזה, וממילא גם עליו אין השליח בא להימלך. שכך \u0003אמר שמואל: דמסוכר ואכל ציפרא\u0004 \u0005[\u0006זה \u0005שמקיז\u0006 דם \u0005ואוכל\u0006 בשר \u0005עוף]\u0006 — \u0003פרח ליביה כציפרא\u0004 \u0005[פורח ליבו כעוף]!\u0006 \u0003ועוד,\u0004 הרי \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 האומרת כן: \u0003אין מקיזין דם לא על\u0004 סמך זה שיאכלו לאחר מכן \u0003הדגים, ולא על\u0004 \u0003העופות, ולא על בשר מליח.\u0004 הרי שאין אוכלים אף בשר עופות ביום הקזה!","\u0003אלא אמר רב פפא:\u0004 אין אנו עוסקים ביום הקזה אלא \u0003ביומא דכייבין ליה עיניה עסקינן\u0004 \u0005[ביום שכואבות לו עיניו עוסקים אנו\u0006 בברייתא זו\u0005],\u0006 \u0003דלא אכיל\u0004 \u0005[שאין\u0006 אדם \u0005אוכל]\u0006 \u0003דגים,\u0004 אבל בשר עופות יכול הוא לאכול.","שנינו במשנתנו שאם \u0003אמר לו\u0004 בעל הבית לשליחו: \u0003\"תן לו\u0004 לכל אורח ואורח \u0003חתיכה\u0004 אחת בלבד של בשר\", והשליח שינה בדבריו ואמר לאורחים שכל אחד מהם יקח שתי חתיכות, והם הוסיפו על דבריו של השליח ולקחו כל אחד מהם שלש חתיכות — כולם מעלו. ואף בעל הבית מעל (על אכילת החתיכה האחת, שכך הורה לו למשלחו). ומסיקים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כלל עקרוני בדין השליחות שבו דנו חכמים, שכל ה\u0003מוסיף על שליחותו,\u0004 שממלא את מה שנאמר לו, ומוסיף דברים שלא נאמרו לו — לא התבטלה בכך שליחותו, ו\u0003הוי\u0004 \u0005[הריהו]\u0006 עדיין \u0003שליח\u0004 לעיקר השליחות!","אמר רב ששת: אין להביא מכאן ראיה לדבר, משום שכאן מדובר בכגון \u0003דאמר\u0004 \u0005[שאומר]\u0006 ה\u0003שליח\u0004 במפורש לאורח: \u0003טול\u0004 חתיכה \u0003אחת מדעתו\u0004 של בעל הבית \u0003ו\u0004חתיכה \u0003אחת מדעתי.\u0004"],["והחידוש שבדבר הוא: \u0003מהו דתימא\u0004 \u0005[\u0006היה מקום \u0005שתאמר]\u0006 כי בכך שהוסיף ואמר שיקחו חתיכה אחת מדעתו, \u0003עקר\u0004 ה\u0003שליח\u0004 את \u0003שליחותיה\u0004 \u0005[שליחותו]\u0006 של \u0003בעל הבית, ולא למעול\u0004 \u0005[ימעול]\u0006 בעל הבית אף בחתיכה הראשונה — לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שכיון שאמר השליח בנתינת החתיכה הראשונה שהיא על דעת בעל הבית — מילא בכך את שליחותו, ובעל הבית מתחייב בה.","\u0003אמר לו\u0004 בעל הבית לשליחו \u0003\"הבא לי\u0004 חפץ זה או מעות אלה \u0003מן החלון\u0004 (שהיו מניחים בו דברים)!\", ולא זכר שהם של הקדש. \u0003או\u0004 שאמר לו להביא לו \u0003מן הדלוסקמא\u0004 (התיבה) בה הם נמצאים. ועשה השליח את שליחותו \u0003והביא לו\u0004 לבעל הבית כפי שביקש. \u0003אף על פי ש\u0004אחר כך \u0003אמר בעל הבית: לא היה בלבי אלא\u0004 (התכוונתי שיביא לי דווקא) \u0003מ\u0004מקום \u0003זה,\u0004 כלומר, מקום אחר ממה שאמרתי, \u0003ו\u0004אילו השליח \u0003הביא\u0004 לי \u0003מ\u0004מקום \u0003זה,\u0004 ולא עשה איפוא את שליחותי — \u0003בעל הבית מעל\u0004 בדבר, שהרי השליח מילא את דברי השליחות כפי שנאמרו לו. \u0003אבל אם אמר לו\u0004 בעל הבית: \u0003\"הבא לי מן ה\u0004דברים הנמצאים ב\u0003חלון!\", והביא לו מן הדלוסקמא, או\u0004 שאמר לו בעל הבית שיביא \u0003מן הדלוסקמא, והביא לו מן החלון\u0004 — \u0003השליח מעל,\u0004 הואיל ושינה מדברי המשלח.","\u0003שלח\u0004 מעות של הקדש \u0003ביד חרש שוטה וקטן,\u0004 שאינם בני דעת, כדי שיקנו בהם דבר מסויים מן החנווני, \u0003אם\u0004 אכן \u0003עשו\u0004 אלה את \u0003שליחותו\u0004 — אף שכלל הוא שכל מי שאין בו דעת, אינו בכלל שליחות — \u0003בעל הבית מעל,\u0004 שהרי התקיימו דבריו. ואולם אם \u0003לא עשו שליחותו\u0004 וקנו מאת החנווני במעות אלה דבר אחר, אם השתמש החנווני במעות שבידו — ה\u0003חנווני מעל.\u0004","\u0003שלח\u0004 בעל הבית את מעות ההקדש \u0003ביד פקח\u0004 (בן דעת), על מנת לקנות לו בהן דבר מן החנווני, \u0003ונזכר\u0004 בעל הבית שהן של הקדש (ושוב אין הוא בכלל דין מעילה, שאין המעילה נוהגת אלא בשימוש בשגגה בהקדש), אם נזכר \u0003עד שלא\u0004 (בטרם) \u0003הגיע\u0004 השליח \u0003אצל\u0004 ה\u0003חנווני\u0004 — ה\u0003חנווני מעל לכשיוציא\u0004 את המעות הללו לשימושו.","ו\u0003כיצד יעשה\u0004 בעל הבית שנזכר שמעות אלה הן של הקדש, ולא יבוא החנווני לידי מעילה? — \u0003נוטל\u0004 בביתו \u0003פרוטה או כלי, ואומר: \"פרוטה של הקדש בכל מקום שהוא\u0004 נמצא בו עתה יהא \u0003מחולל על\u0004 פרוטה או כלי \u0003זה\",\u0004 ומתחללים בכך מעות ההקדש על פרוטה זו או כלי זה, \u0003ש\u0004כן הלכה היא כי \u0003ההקדש נפדה\u0004 ומתחלל הן בכסף הן \u0003ב\u0004דבר ה\u0003שוה כסף,\u0004 כגון כלי. ונמצא שהמעות שביד החנווני חולין ואין בהם מעילה.","שנינו בתחילת המשנה שאם עשה השליח כדברי בעל הבית, אף על פי שלטענת בעל הבית כוונתו היתה למקום אחר, ולדבריו לא התקיימה איפוא שליחותו — בעל הבית הוא שמעל. ומסבירים: \u0003מאי קא משמע לן\u0004 \u0005[מה הוא\u0006 התנא שבמשנתנו \u0005השמיע לנו]\u0006 בכך? — שה\u0003דברים שבלב\u0004 שלא נאמרו במפורש בפה \u0003אינם\u0004 נחשבים \u0003דברים,\u0004 ואין מתחשבים בהם אלא רק בדברים המפורשים בפה.","שנינו במשנתנו שאם \u0003שליח\u0004 בעל הבית את מי שאינו בן דעת שיקנה לו חפץ מן החנווני ונתן לו מעות הקדש לכך, וכגון שנתן \u0003ביד חרש שוטה וקטן, אם עשו\u0004 את דבריו — בעל הבית מעל. ושואלים: \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003בני שליחותא נינהו\u0004 \u0005[שליחות הם],\u0006 ומדוע איפוא יתחייב בעל הבית במעילה על מעשיהם?","\u0003אמר ר' אלעזר: עשאום\u0004 חכמים, כלומר, קבעו את דינם \u0003כ\u0004דין \u0003מעטן\u0004 (כלי גדול) \u0003של זיתים\u0004 לענין קבלת טומאה, שכיון שנוח לו לבעל הבית במוהל היוצא מן הזיתים שבמעטן — הרי זה נחשב כאילו נעשה מדעתו והוכשרו הזיתים לקבל טומאה. ואף בענייננו, כיון שנוח לו לבעל הבית שהתקיימו דבריו על ידי אלה — הרי זה נחשב כאילו נעשה הדבר מדעתו.","ומהו עניינו של המעטן, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אחר שכלל הוא שכל מאכלי האדם אינם ראויים להיטמא אלא אם כן בא עליהם תחילה משקה (משבעת המשקים המכשירים: מים, טל, שמן, יין, חלב, דם, דבש), ואולם צריך שתהיה נתינת משקה זה לדעתו ולרצונו של בעל הדבר, מעתה, \u0003הזיתים\u0004 לאחר מסיקתם מן העץ, \u0003מאימתי\u0004 הם \u0003מקבלין\u0004 (ראויים לקבל) \u0003טומאה?\u0004 — \u0003משיזיעו\u0004 (יוציאו מוהל) ב\u0003זיעת המעטן,\u0004 \u0003ולא\u0004 לפני כן ב\u0003זיעת הקופה\u0004 (הסל המשמש ללקיטתם מן העץ). שכן המוהל היוצא מהם בהיותם במעטן — הוא לרצונו של בעל הבית, שהרי בכך מתרככים הזיתים וייקל לסוחטם לשמן, ואף אין זיעה זו אובדת לו. מה שאין כן זיעת הקופה — שאינה לרצונו, וגם היא הולכת לאיבוד.","\u0003ר' יוחנן אמר: כאותה\u0004 הלכה \u0003ששנינו\u0004 בברייתא בדין נתינת עירוב (תחומים או חצרות) לשבת, שאם \u0003נתנו על גבי הקוף\u0004 המאולף לכך, \u0003והוליכו\u0004 הקוף את העירוב והניחו במקום שנקבע לו להניח. \u0003או\u0004 שהניח את העירוב \u0003על גבי הפיל והוליכו\u0004 הפיל למקום שנקבע לו. \u0003ו\u0004כן אם \u0003אמר ל\u0004אדם \u0003אחר לקבלו ממנו\u0004 מעל גבי הקוף או הפיל ולהניחו במקומו, ועשו כן — \u0003הרי זה עירוב\u0004 תחומין או עירוב חצרות כשר, ויכול הוא ללכת על סמך עירוב תחומין זה אלפיים אמה ממקומו של העירוב. וכן יכול הוא לטלטל מביתו לחצר ומחצר לביתו על סמך עירוב חצרות זה. \u0003אלמא קא עבדא שליחותיה\u0004 \u0005[מכאן,\u0006 שנחשב הדבר ש\u0005הוא,\u0006 הקוף או הפיל, \u0005עשה\u0006 את \u0005שליחותו]\u0006 אף על פי שאין הוא בן שליחות, כיון שהדבר הוא לרצונו של בעל הבית. \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בדין אלה שאינם בני דעת, \u0003איתעביד שליחותיה\u0004 \u0005[נעשתה שליחותו],\u0006 ובעל הבית מעל.","שנינו במשנתנו שאם בעל הבית \u0003שלח\u0004 מעות הקדש \u0003ביד פקח\u0004 לקנות בהם מאת החנווני, ונזכר בעל הבית שהן של הקדש לפני שהגיע השליח לחנווני — חל דין המעילה על החנווני משעה שיוציאם. ושואלים על כך: מדברים אלה עולה שהחנווני הוא המועל, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 שרק בעל הבית הוא שנזכר ו\u0003לא אידכר\u0004 \u0005[נזכר]\u0006 גם ה\u0003שליח.\u0004 ואולם אם נזכר גם השליח — החנווני מעל שהרי רק אצל החנווני היא שגגה. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]:\u0006 לכך ממה ששנינו בברייתא: \u0003נזכר בעל הבית\u0004 שהמעות הן של הקדש \u0003ולא נזכר\u0004 ה\u0003שליח\u0004 בכך — \u0003השליח\u0004 הוא ש\u0003מעל.\u0004 ואם \u0003נזכרו שניהם\u0004 שהמעות הן של הקדש — ה\u0003חנוני מעל!\u0004","\u0003אמר רב ששת: מתניתין נמי\u0004 \u0005[משנתנו גם כן]\u0006 הקובעת שחנווני מעל, מדברת \u0003כשנזכרו שניהם,\u0004 בעל הבית והשליח.","\u0003נתן לו\u0004 בעל הבית לשליח בשוגג \u0003פרוטה\u0004 של הקדש, ו\u0003אמר לו: \"הבא\u0004 (קנה) \u0003לי בחציה\u0004 האחד של פרוטה זו \u0003נרות\u0004 (כלי למאור) \u0003ובחציה\u0004 האחר \u0003פתילות\u0004 לנרות\". \u0003והלך\u0004 השליח \u0003והביא לו ב\u0004פרוטה \u0003כולה פתילות, או\u0004 שהביא לו \u0003בכולה נרות. או שאמר לו: \"הבא לי בכולה נרות\", או\u0004 \"הבא לו \u0003בכולה פתילות\", והלך\u0004 שליח \u0003והביא בחציה נרות ובחציה פתילות\u0004 — \u0003שניהם לא מעלו\u0004 בכך. בעל הבית לא מעל — שכן לא נתקיימו דבריו על ידי השליח אלא בחצי פרוטה, ואין בכך שיעור מעילה. ואף השליח לא מעל בכך — שהרי לא עשה על דעת עצמו אלא רק בחצי פרוטה.","\u0003אבל אם אמר לו\u0004 בעל הבית לשליח \u0003\"הבא לי בחציה\u0004 של פרוטה זו \u0003נרות ממקום פלוני, ובחציה פתילות ממקום פלוני!\", והלך\u0004 השליח \u0003והביא לו נרות\u0004 בחצי פרוטה ואולם לא הביאם ממקום נרות כפי שאמר לו בעל הבית אלא \u0003ממקום פתילות. ו\u0004כן הביא \u0003פתילות\u0004 בחצי פרוטה \u0003ממקום נרות\u0004 — \u0003השליח מעל,\u0004 שהרי שינה בשליחותו, בין בנרות ובין בפתילות, ויש בדבר שיעור מעילה שבכדי פרוטה.","\u0003נתן לו\u0004 בעל הבית לשליח \u0003שתי פרוטות\u0004 של הקדש ולא ידע שהם של הקדש, \u0003ואמר לו \"לך והבא לי\u0004 בהן \u0003אתרוג!\", והלך\u0004 השליח \u0003והביא לו ב\u0004פרוטה \u0003אחת אתרוג וב\u0004פרוטה \u0003אחת רימון\u0004 — \u0003שניהם מעלו,\u0004 בעל הבית מעל — שהרי נעשתה שליחותו בשיעור פרוטה, והשליח מעל — שהרי שינה שליחותו בשיעור כדי מעילה, בפרוטה (שקנה את הרימון). \u0003ר' יהודה אומר: בעל הבית לא מעל, ש\u0004כן \u0003הוא אומר\u0004 (יכול לומר) \u0003לו\u0004 לשליח: כל מה שעשית היה שינוי שליחות, ואף קניית האתרוג בכלל זה, כי \u0003אתרוג גדול\u0004 (הנקנה בשתי פרוטות) \u0003הייתי מבקש, ו\u0004אילו אתה \u0003הבאת לי\u0004 אתרוג \u0003קטן ורע\u0004 בפרוטה אחת.","\u0003נתן לו\u0004 בעל הבית לשליח מכסף הקדש שבידו \u0003דינר זהב\u0004 של הקדש (שיש בדינר זהב עשרים וחמישה דינרי כסף, וארבעה דינרי כסף הם סלע. ראה עיונים בעמ' הבא), \u0003ואמר לו: לך והבא לי\u0004 בו \u0003חלוק,\u0004"],["\u0003והלך\u0004 השליח \u0003והביא לו בשלשה\u0004 סלעים מתוך דינר הזהב שקיבל \u0003חלוק, ובשלשה\u0004 סלעים אחרים \u0003טלית\u0004 — \u0003שניהם מעלו.\u0004 בעל הבית מעל — שהרי נעשתה שליחותו בקניית החלוק בשלושת הסלעים, והשליח מעל — שהרי שינה משליחותו של בעל הבית בשלושת הסלעים האחרים, שקנה בהם מדעתו טלית. \u0003ר' יהודה אומר: בעל הבית לא מעל, ש\u0004כן \u0003הוא אומר\u0004 (יכול לומר) \u0003לו\u0004 לשליח: שינית משליחותך אף בקניית החלוק בשלושת הסלעים, כי \u0003חלוק גדול\u0004 (הנקנה בדינר זהב) \u0003הייתי מבקש, ו\u0004אילו אתה \u0003הבאת לי\u0004 במקומו חלוק \u0003קטן ורע\u0004 הנקנה בשלושה סלעים.","מדין משנתנו משמע שהשליח המוסיף על דברי המשלח (לענין הטלית), נחשב גם כעושה שליחותו (לענין החלוק). ומציעים: \u0003שמעת מינה\u0004 \u0005[לומד אתה מכאן]\u0006 פתרון לבעייה שדנו בה חכמים, במסכת כתובות, בעניינו של \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003לשלוחו: זיל זבן\u0004 \u0005[לך מכור]\u0006 \u0003לי\u0004 (עבורי) מתוך שדותי \u0003כורא דארעא\u0004 \u0005[\u0006שטח שמידתו \u0005בית כור של קרקע],\u0006 \u0003ואזל\u0004 \u0005[והלך]\u0006 השליח \u0003וזבן ליה\u0004 \u0005[ומכר לו]\u0006 קרקע במידת \u0003ליתכא\u0004 \u0005[לתך,\u0006 חצי בית כור] בלבד — חל המכר, ו\u0003קני\u0004 \u0005[קנה]\u0006 ה\u0003לוקח\u0004 (הקונה) את הקרקע בשיעור לתך שנמכרה לו, שכן נחשב הדבר שעשה בכך השליח שליחותו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיית הראיה: אין להביא מכאן הוכחה כי \u0003הכא היכי דמי\u0004 \u0005[כאן,\u0006 במשנתנו \u0005כיצד מדובר]?\u0006 \u0003כגון דאייתי ליה\u0004 \u0005[שהביא לו]\u0006 השליח לבעל הבית חלוק ה\u0003שוה שש\u0004 סלעים, כערך דינר הזהב שנתן לו בעל הבית, \u0003בשלש\u0004 סלעים, וקיבל בעל הבית בדיוק את מה שרצה, ולא שינה השליח מדבריו אלא רק הוסיף עליהם, בזה שקנה לו גם טלית. אבל במקום שלא עשה את שליחותו, כגון במכירת שדה שמכר פחות ממה שנאמר לו, אין זו נחשבת לשליחות.","ומקשים על אופן העמדה זו של משנתנו: אם כך, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את מה ששנינו ב\u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003ר' יהודה אומר: בעל הבית לא מעל, ש\u0004כן \u0003הוא יכול לומר לו \"חלוק גדול הייתי מבקש, ו\u0004אילו אתה \u0003הבאת לי חלוק קטן ורע\"\u0004 והרי שאין מדובר כאן באופן שהביא לו השליח חלוק השווה ששה סלעים, אלא \"חלוק קטן ורע\"!","ומשיבים: כוונת דברי ר' יהודה היא, \u0003דאמר ליה\u0004 \u0005[ש\u0006כך יכול \u0005לומר לו]\u0006 בעל הבית לשליח: כיון שקנית במקום בו המחירים הם מחצית מהמחירים הרגילים, מעתה \u0003אי יהבת\u0004 \u0005[אם היית נותן,\u0006 מוציא\u0005]\u0006 בקנייה שעשית עבורי את ה\u0003דינר כוליה\u0004 \u0005[כולו]\u0006 שנתתי לך, \u0003אייתית\u0004 \u0005[יכול היית להביא]\u0006 \u0003לי\u0004 בדינר זה חלוק משובח ביותר ה\u0003שוה שני דינרין,\u0004 ובהשוואה לאותו חלוק, מה שהבאת לי הוא \"קטן ורע\".","ומוסיפים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להעמיד את דברי ר' יהודה, \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא \u0005בסוף,\u0006 במקום אחר\u0005]:\u0006 \u0003מודה ר' יהודה\u0004 לחכמים, במקרה של בעל הבית ששלח שליח שיקנה לו קטניות בדינר זהב, והלך השליח וקנה \u0003ב\u0004חצי דינר \u0003קטנית,\u0004 ובחצי דינר קנה דבר אחר — \u0003ששניהם מעלו,\u0004 ואף בעל הבית מעל (על קניית הקטנית). וטעם הדבר, שמחיר הקטנית הינו קבוע ובלתי משתנה, \u0003שהקטנית\u0004 בשיעור מסויים נקנית \u0003בפרוטה וקטנית\u0004 בשיעור גדול ממנו נקנית \u0003בדינר,\u0004 על פי אותו תעריף, ואין הוזלה כלשהי לקונה בסכום גדול יותר. ומשמע שבדבר אחר, וכגון חלוק, קנייה בסכום גדול יותר מוזילה את מחיר הדבר הנקנה.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר],\u0006 באיזה מקום מדובר כאן? \u0003אי באתרא דזבני בשומא\u0004 \u0005[אם\u0006 תאמר שמדובר \u0005במקום שמוכרים\u0006 קטניות \u0005בהערכה],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 מכירת \u0003קטנית נמי\u0004 \u0005[גם כן],\u0006 במקרה \u0003דיהב\u0004 \u0005[שנותן]\u0006 הקונה למוכר סכום גבוה כגון \u0003סלע מוזלי ליה טפי\u0004 \u0005[מוזילים לו יותר]\u0006 מאשר אם היה קונה בסכום נמוך! אמר רב פפא: מדובר \u0003בדוכתא דמזבני בכני כני\u0004 \u0005[במקום שמוכרים ב\u0006מלוא \u0005כלים כלים],\u0006 כלומר, שמשלם הקונה בהתאם למספר הכלים בהם ניתנות הקטניות, מחיר כל \u0003כנא\u0004 ו\u0003כנא\u0004 \u0005[כלי כלי]\u0006 \u0003בפרוטה, דהתם פסיק מילתייהו\u0004 \u0005[ששם דבריהם חתוכים,\u0006 המחיר קבוע\u0005],\u0006 ולכן באופן זה מעל גם בעל הבית.","אדם \u0003המפקיד מעות\u0004 של הקדש שבידו \u0003אצל\u0004 ה\u0003שולחני\u0004 (חלפן כספים), הפורט ומעביר כספים מיד ליד, ונזקק תמיד לכספים, \u0003אם\u0004 נמסרו לו המעות הללו כשהן \u0003צרורין\u0004 (קשורות) — \u0003לא ישתמש בהן\u0004 השולחני. \u0003לפיכך, אם\u0004 עבר ו\u0003הוציא\u0004 אותם לצרכיו — \u0003מעל\u0004 השולחני. ואולם \u0003אם\u0004 המעות שנמסרו היו \u0003מותרין\u0004 (לא קשורות) — \u0003ישתמש\u0004 (מותר לו להשתמש) \u0003בהן. לפיכך, אם הוציא\u0004 אותם — \u0003לא מעל\u0004 השולחני. ואולם המפקיד מעות \u0003אצל בעל הבית\u0004 — \u0003בין כך\u0004 (שהיו המעות קשורות) \u0003ובין כך\u0004 (שהיו מותרות) — \u0003לא ישתמש בהן. לפיכך, אם הוציא\u0004 אותם בעל הבית — \u0003מעל. החנווני,\u0004 הקונה ומוכר סחורות בחנות, נחשב לענין זה \u0003כבעל הבית,\u0004 ואסור לו להשתמש במעות שהופקדו בידו, ואם הוציאן — מעל. אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 החנווני נחשב לענין זה \u0003כשולחני,\u0004 והריהו אסור בשימוש במעות צרורות שהופקדו בידו, ומותר בשימוש במעות מותרות שהופקדו בידו.","\u0003נפלה פרוטה של הקדש בתוך כיסו\u0004 (ארנקו) של אדם שהיו בו פרוטות אחרות של חולין, \u0003או שאמר\u0004 על פרוטה אחת מתוך המעות שהיו בארנקו \u0003\"פרוטה\u0004 ש\u0003בכיס זה\u0004 הריהי \u0003הקדש!\",\u0004 ואין הוא יודע איזוהי אותה פרוטה — \u0003כיון שהוציא את\u0004 הפרוטה \u0003הראשונה\u0004 מארנקו לצורך של חולין, \u0003מעל,\u0004 אלו \u0003דברי ר' עקיבא,\u0004 שלדעתו חוששים אנו שמא זו היא שהיתה של הקדש. וכך הוא הדין בכל פרוטה ופרוטה שיוציא מכיסו זה, יש לחשוש שמא היא הפרוטה של ההקדש. \u0003וחכמים אומרים:\u0004 לא מעל \u0003עד שיוציא\u0004 לחולין \u0003את כל ה\u0004פרוטות הנמצאות ב\u0003כיס,\u0004 שאז ודאי שהוציא פרוטה של הקדש.","\u0003ו\u0004מעירים: \u0003מודה ר' עקיבא לחכמים ב\u0004מקרה של ה\u0003אומר \"פרוטה\u0004 אחת \u0003מן\u0004 המעות שב\u0003כיס זה\u0004 הריהי \u0003הקדש!\", שהוא מוציא\u0004 לחולין \u0003והולך\u0004 (וממשיך בכך) \u0003עד שיוציא את כל ה\u0004מעות שב\u0003כיס\u0004 כולן. שכן לשון זו מורה שכוונתו היתה שהפרוטה האחרונה שתישאר בארנק היא זו שתהיה הקדש, ולכן אין הוא מועל אלא בפרוטה זו.","שנינו בסוף משנתנו כי מודה ר' עקיבא לחכמים באדם המקדיש פרוטה שבכיסו בלשון \"פרוטה מן כיס זה הקדש!\" שאין הוא מועל אלא בפרוטה האחרונה שהוציא מהכיס. ובענין זה מוסרים: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 כי \u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 \u0003ריש לקיש לר' יוחנן\u0004 בדברי ר' עקיבא שבמשנתנו. וכך שאל אותו: \u0003מאי שנא רישא\u0004 \u0005[מה שונה\u0006 הוא הדין שב\u0005ראש\u0006 המשנה\u0005]\u0006 באדם האומר \"פרוטה בכיס זה הקדש!\" שחולק ר' עקיבא על חכמים וסבור שמועל בהוצאת הפרוטה הראשונה שבכיס, \u0003ומאי שנא סיפא\u0004 \u0005[ומה שונה\u0006 הוא הדין שב\u0005סוף\u0006 המשנה\u0005]\u0006 באדם האומר \"פרוטה מן כיס זה הקדש!\" שמודה ר' עקיבא לחכמים שאין הוא מועל אלא בפרוטה האחרונה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לריש לקיש בהסבר הדברים: \u0003סיפא\u0004 \u0005[הסוף]\u0006 של המשנה עוסק \u0003ב\u0004אדם ה\u0003אומר\u0004 בלשון \u0003\"לא יפטור כיס זה מן ההקדש\",\u0004 וכוונתו שלא תכלה פרוטה מן הכיס הזה עד שיהא בו הקדש, ונמצא שחל ההקדש רק על הפרוטה האחרונה.","ועוד נמסר: \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל הביא את הדברים באופן אחר ו\u0003אמר\u0004 כי בין משנתנו שעניינה \u0003כיסין\u0004 לבין משנה אחרת שעניינה \u0003שוורים\u0004 הוא ש\u0003רמא ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 ריש לקיש לר' יוחנן. \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]\u0006 במסכת מנחות: \u0003האומר \"אחד משווריי\u0004 הריהו \u0003הקדש!\",\u0004 והיו לו שנים שוורים, ואין ידוע איזה מהם הקדיש — \u0003הגדול שבהן\u0004 הוא שור ה\u0003הקדש!\u0004 וטעם הדבר, לפי הכלל שהמקדיש בעין יפה מקדיש, וודאי התכוון לגדול שבהם. ומעתה לפי זה אף במשנתנו נאמר שהפרוטה היותר מובחרת היא זו שהקדישה! ועל כך \u0003אמר לו\u0004 ר' יוחנן בתשובה: \u0003סיפא\u0004 \u0005[סוף]\u0006 משנתנו עוסק \u0003ב\u0004אדם ה\u0003אומר\u0004 בלשון \u0003\"לא יפטור כיס זה מן ההקדש\",\u0004 והרי משמעות לשון זו שאין כוונתו אלא על הפרוטה האחרונה, אף שאין היא המובחרת שבפרוטות."],["\u0003רב פפא אמר:\u0004 בין משנתנו זו שעניינה \u0003כיסין\u0004 (פרוטת הקדש הנמצאת בכיס מעות חולין) ובין המשנה במסכת דמאי שעניינה \u0003לוגין\u0004 הוא ש\u0003רמא ליה\u0004 \u0005[השליך לו,\u0006 הראה סתירה\u0005]\u0006 ריש לקיש לר' יוחנן. \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו]: \u0003הלוקח\u0004 (הקונה) \u0003יין מבין הכותים\u0004 (שומרונים), לשיטה שהם מפרישים תרומות ומעשרות, אלא שאין הם מפרישים אלא לעצמם ולא מן הדברים שהם מוכרים, והרי זה איפוא טבל ודאי. ואין הקונה יכול עתה להפריש תרומות ומעשרות מיין זה (כגון שקנה את היין לפני כניסת השבת, ולא היתה בידו אפשרות לעשר עד כניסת השבת), מה יעשה על מנת שיוכל לשתות מיין זה בשבת?","— הריהו \u0003אומר \"שני לוגין\u0004 מתוך מאה הלוגים שלפני \u0003שאני עתיד להפריש\u0004 מיין זה לאחר זמן — \u0003הרי הן\u0004 מעתה \u0003תרומה\u0004 גדולה. ו\u0003עשרה\u0004 לוגים שאני עתיד לעשר ולתיתם ללוי — ל\u0003מעשר ראשון,\u0004 וכן \u0003תשעה\u0004 לוגים (עשירית מן הנשאר) שאני עתיד להפרישם הריהם \u0003מעשר שני!\". ומיחל\u0004 \u0005[ומחלל]\u0006 את המעשר השני על כסף \u0003ו\u0004אם רוצה, הריהו \u0003שותה מיד\u0004 (פרט לשיעור תרומה ומעשרות), וסומך על מה שיפריש לאחר מכן, שאז יתבררו הלוגים שהופרשו לתרומה ולמעשרות. אלו דברי ר' מאיר. \u0003ר' יהודה ור' יוסי ור' שמעון אוסרים,\u0004 שלדעתם אין אומרים שלאחר מכן יתברר מה הופרשו לתרומה ולמעשר. נמצא שאף לדעת ר' מאיר, הרי זה רק באומר \"שאני עתיד להפריש\", ובהסתמך על כך שיתברר הדבר בסוף איזה הם אותם לוגים שהופרשו. ואילו בסוף משנתנו שנינו לדעת ר' עקיבא שמותר להוציא את כל הפרוטות שבכיס, ואף שלא אמר המקדיש שההקדש יחול על הפרוטה שהוא עתיד להפריש לאחר מכן! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן בתשובה לדבר: \u0003סיפא דמתניתין\u0004 \u0005[\u0006ב\u0005סוף משנתנו]\u0006 מדובר \u0003ב\u0004אדם ה\u0003אומר\u0004 בלשון \u0003\"לא יפטר כיס זה מן ההקדש!\",\u0004 והרי זה כאדם האומר \"שאני עתיד להקדיש\", ולכשיעלה את הפרוטה האחרונה מן הכיס, יתברר הדבר שהיא הפרוטה שהוקדשה.","",""]]};
